   "name": {
    "he": "יציאות השבת",
    "en": "Carrying out on Shabbos"
   },
   "text": "יְצִיאוֹת הַשַּׁבָּת שְׁתַּיִם שֶׁהֵן אַרְבַּע בִּפְנִים, וּשְׁתַּיִם שֶׁהֵן אַרְבַּע בַּחוּץ. כֵּיצַד. הֶעָנִי עוֹמֵד בַּחוּץ וּבַעַל הַבַּיִת בִּפְנִים, פָּשַׁט הֶעָנִי אֶת יָדוֹ לִפְנִים וְנָתַן לְתוֹךְ יָדוֹ שֶׁל בַּעַל הַבַּיִת, אוֹ שֶׁנָּטַל מִתּוֹכָהּ וְהוֹצִיא, הֶעָנִי חַיָּב וּבַעַל הַבַּיִת פָּטוּר. פָּשַׁט בַּעַל הַבַּיִת אֶת יָדוֹ לַחוּץ וְנָתַן לְתוֹךְ יָדוֹ שֶׁל עָנִי, אוֹ שֶׁנָּטַל מִתּוֹכָהּ וְהִכְנִיס, בַּעַל הַבַּיִת חַיָּב וְהֶעָנִי פָּטוּר. פָּשַׁט הֶעָנִי אֶת יָדוֹ לִפְנִים וְנָטַל בַּעַל הַבַּיִת מִתּוֹכָהּ, אוֹ שֶׁנָּתַן לְתוֹכָהּ וְהוֹצִיא, שְׁנֵיהֶם פְּטוּרִין. פָּשַׁט בַּעַל הַבַּיִת אֶת יָדוֹ לַחוּץ וְנָטַל הֶעָנִי מִתּוֹכָהּ, אוֹ שֶׁנָּתַן לְתוֹכָהּ וְהִכְנִיס, שְׁנֵיהֶם פְּטוּרִין:",
   "gap": {
    "he": "לפי לשון המשנה, יש שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ, וכולן נקראות יציאות. רב פפא מסביר שכאן, בעיקר הלכות שבת, המשנה מונה גם פטורים, ושתים הן הוצאה ושתים הכנסה. איך הכנסה נקראת יציאה? לרב אשי התנא קורא לכל עקירה הוצאה, ולרבא המשנה מדברת על רשויות. רבינא מדייק שהמשנה אומרת יציאות ומיד מפרשת הכנסה. הפטורים שנמנו הם רק אלה שיכולים להביא לידי חיוב חטאת, ושניהם פטורים משום ששנים שעשו מלאכה יחד פטורים. ואיך היד נחשבת מקום לעקירה והנחה: לרבי אבא בטרסקל שבידו, לרבי אבהו כששלשל ידו למטה משלשה, ולרבא ידו של אדם חשובה כארבעה על ארבעה.",
    "en": "As written, there are two that are four inside and two that are four outside, and all are called yetzios. Rav Pappa explains that here, in the core laws of Shabbos, the Mishnah lists exempt cases too, and the pairs are two of carrying out and two of carrying in. How is carrying in called yetzia? For Rav Ashi the Tanna calls every lifting of an object hotza'ah; for Rava the Mishnah is speaking of reshuyos, domains. Ravina infers it from the Mishnah itself, which says yetzios and immediately spells out carrying in. The exempt cases counted are only those that can lead to a chatas obligation, and where both are exempt it is because two who do a melachah together are exempt. And how does a hand count as a place for lifting and setting down: for Rabbi Abba, a basket in his hand; for Rabbi Abahu, when he lowered his hand below three tefachim; for Rava, a person's hand counts as four by four."
   },
