   "text": "לֹא יֵשֵׁב אָדָם לִפְנֵי הַסַּפָּר סָמוּךְ לַמִּנְחָה, עַד שֶׁיִּתְפַּלֵּל. לֹא יִכָּנֵס אָדָם לַמֶּרְחָץ וְלֹא לַבֻּרְסְקִי וְלֹא לֶאֱכֹל וְלֹא לָדִין. וְאִם הִתְחִילוּ, אֵין מַפְסִיקִין. מַפְסִיקִים לִקְרוֹת קְרִיאַת שְׁמַע, וְאֵין מַפְסִיקִים לַתְּפִלָּה:",
   "gap": {
    "he": "לפי לשון המשנה, סמוך למנחה לא יתחיל אדם בתספורת, מרחץ, בורסקי, אכילה ודין, ואם התחילו אין מפסיקין. הגמרא נחלקת בהבנה: לשיטה אחת מדובר סמוך למנחה גדולה ובדברים ארוכים, כמו תספורת בן אלעשה וסעודה גדולה, ולרב אחא בר יעקב מדובר בתספורת שלנו ובסעודה קטנה, והאיסור הוא גזירה שמא יישבר הזוג או שמא יימשך. רב אבין מגדיר מתי נקראת התחלה בתספורת ובמרחץ. בהתחלת אכילה, לרב משיטול ידיו ולרבי חנינא משיתיר חגורו, ולא פליגי, זה לבבל וזה לארץ ישראל. הסיפא, מפסיקין לקריאת שמע, עוסקת בלומדי תורה, ורבי יוחנן מעמיד אותה רק במי שתורתו אומנותו.",
    "en": "As written, close to Minchah one may not begin a haircut, the bathhouse, the tannery, a meal or a court case, and if they began they need not stop. The Gemara reads it two ways: one view says it means close to the early Minchah and long activities, like the haircut of Ben Elasah and a large feast; Rav Acha bar Yaakov says it means our ordinary haircut and a small meal, and the ban is a gezeirah lest the scissors break or the meal drag on. Rav Avin defines when a haircut and a bath count as begun. For a meal, Rav says once he washes his hands and Rabbi Chanina says once he loosens his belt, and they do not disagree: one speaks of Bavel, the other of Eretz Yisrael. The seifa, that one stops for Krias Shema, speaks of people learning Torah, and Rabbi Yochanan limits it to those whose Torah is their occupation."
   },
