   "link": "https://www.sefaria.org/Mishnah_Shabbat.2.1",
   "name": {
    "he": "במה מדליקין",
    "en": "What may be used for lighting"
   },
   "text": "בַּמֶּה מַדְלִיקִין וּבַמָּה אֵין מַדְלִיקִין. אֵין מַדְלִיקִין לֹא בְלֶכֶשׁ, וְלֹא בְחֹסֶן, וְלֹא בְכָלָךְ, וְלֹא בִפְתִילַת הָאִידָן, וְלֹא בִפְתִילַת הַמִּדְבָּר, וְלֹא בִירוֹקָה שֶׁעַל פְּנֵי הַמָּיִם. וְלֹא בְזֶפֶת, וְלֹא בְשַׁעֲוָה, וְלֹא בְשֶׁמֶן קִיק, וְלֹא בְשֶׁמֶן שְׂרֵפָה, וְלֹא בְאַלְיָה, וְלֹא בְחֵלֶב. נַחוּם הַמָּדִי אוֹמֵר, מַדְלִיקִין בְּחֵלֶב מְבֻשָּׁל. וַחֲכָמִים אוֹמְרִים, אֶחָד מְבֻשָּׁל וְאֶחָד שֶׁאֵינוֹ מְבֻשָּׁל, אֵין מַדְלִיקִין בּוֹ:",
   "gap": {
    "he": "לפי לשון המשנה, יש רשימה אחת של פתילות ושמנים שאין מדליקין בהם, בלי טעם ובלי גבול. הגמרא מפרשת את המילים: לכש הוא שוכא דארזא בגלל הצמר שבו, אידן הוא אחוינא, פתילת המדבר היא שברא, זפת היא זיפתא ושעוה היא קירותא. ברייתא מחלקת את הרשימה, עד כאן פסולי פתילות ומכאן פסולי שמנים, ושעוה נשנית בשמנים כדי ללמד שהיא כשרה לפתילה. ברייתא אחרת מגבילה: האיסור הוא רק לעשות מהם פתילה לנר, אבל מדורה מהם מותרת. רבה נותן את הטעם: בפתילות האור מסכסכת בהן, והשמנים אינם נמשכים אחר הפתילה. בשמן שריפה, רבה אומר שהוא תרומה טמאה ואסור בשבת גזירה שמא יטה, ורב חסדא אומר שלא חוששים לשמא יטה, והמשנה עוסקת ביום טוב שחל להיות ערב שבת. ובין חכמים לתנא קמא ההבדל הוא דינו של רב ברונא, ולא מפורש מי אוחז מה.",
    "en": "As written, the Mishnah gives one list of wicks and oils that may not be used for lighting, with no reason and no limit. The Gemara defines the words: lechesh is the cedar's inner fiber, idan is a willow bast, the wilderness wick is a weed, zefes is pitch and sha'avah is wax. A baraisa divides the list: up to here are invalid wicks, from here on invalid oils, and wax is listed with the oils to teach that it is fit as a wick. Another baraisa limits it: the ban is only on making them a wick for a lamp, while a bonfire of them is allowed. Rabbah gives the reason: the flame flickers on those wicks, and those oils are not drawn up the wick. On shemen sereifah, Rabbah says it is tamei terumah, forbidden on Shabbos lest one tilt the lamp, while Rav Chisda says we do not worry about tilting and the Mishnah speaks of Yom Tov falling on Erev Shabbos. And between the Chachamim and the tanna kamma the difference is Rav Berona's ruling, and it is not stated who holds which."
   },
