   "text": "לֹא יִקֹּב אָדָם שְׁפוֹפֶרֶת שֶׁל בֵּיצָה וִימַלְאֶנָּה שֶׁמֶן וְיִתְּנֶנָּה עַל פִּי הַנֵּר בִּשְׁבִיל שֶׁתְּהֵא מְנַטֶּפֶת, אֲפִלּוּ הִיא שֶׁל חֶרֶס. וְרַבִּי יְהוּדָה מַתִּיר. אֲבָל אִם חִבְּרָהּ הַיּוֹצֵר מִתְּחִלָּה, מֻתָּר, מִפְּנֵי שֶׁהוּא כְלִי אֶחָד. לֹא יְמַלֵּא אָדָם אֶת הַקְּעָרָה שֶׁמֶן וְיִתְּנֶנָּה בְצַד הַנֵּר וְיִתֵּן רֹאשׁ הַפְּתִילָה בְתוֹכָהּ, בִּשְׁבִיל שֶׁתְּהֵא שׁוֹאֶבֶת. וְרַבִּי יְהוּדָה מַתִּיר:",
   "gap": {
    "he": "לפי לשון המשנה, חכמים אוסרים לתת שפופרת של ביצה על פי הנר, ואפילו של חרס, או קערה בצד הנר, ורבי יהודה מתיר, בלי טעם. הגמרא מסבירה שבשפופרת של ביצה חכמים חוששים שכיון שאינה מאוסה יבוא להסתפק ממנה, ולכן צריך לומר גם של חרס; ובקערה, שהיא נפרדת מהנר, צריך לומר שרבי יהודה מתיר גם בה. ברייתא מרחיבה את חיברה היוצר: גם חיבור בסיד ובחרסית מותר, ויוצר פירושו כעין יוצר.",
    "en": "As written, the Chachamim forbid placing an eggshell over the lamp's mouth, even one of earthenware, or a bowl beside the lamp, and Rabbi Yehudah permits, with no reason given. The Gemara explains that with an eggshell the Chachamim worry that since it is not repulsive one will come to take oil from it, so earthenware has to be stated too; and with the bowl, which stands apart from the lamp, it has to be stated that Rabbi Yehudah permits even that. A baraisa widens \"if the potter attached it\": attaching it with lime or clay is also allowed, and \"potter\" means like a potter's work."
   },
