   "text": "הַמְכַבֶּה אֶת הַנֵּר מִפְּנֵי שֶׁהוּא מִתְיָרֵא מִפְּנֵי גוֹיִם, מִפְּנֵי לִסְטִים, מִפְּנֵי רוּחַ רָעָה, וְאִם בִּשְׁבִיל הַחוֹלֶה שֶׁיִּישַׁן, פָּטוּר. כְּחָס עַל הַנֵּר, כְּחָס עַל הַשֶּׁמֶן, כְּחָס עַל הַפְּתִילָה, חַיָּב. וְרַבִּי יוֹסֵי פּוֹטֵר בְּכֻלָּן חוּץ מִן הַפְּתִילָה, מִפְּנֵי שֶׁהוּא עוֹשָׂהּ פֶּחָם:",
   "gap": {
    "he": "לפי לשון המשנה, המכבה מפחד או בשביל החולה פטור, והמכבה כחס על הנר חייב, ורבי יוסי פוטר בכולן חוץ מן הפתילה. מהסיפא שמחייב מסיקה הגמרא שהמשנה כשיטת רבי יהודה. הרישא עוסקת בחולה שיש בו סכנה, ובאמת מותר, ונשנה פטור רק משום הסיפא חייב. בשיטת רבי יוסי נחלקו: עולא אומר שהוא כרבי יהודה וסובר שסותר על מנת לבנות שלא במקומו אינו סותר, ורבי יוחנן אומר שהוא כרבי שמעון והמשנה עוסקת בפתילה שצריך להבהבה, שבזה מתקן כלי. ורבא מדייק כך מהלשון שהוא עושה פחם, ולא שנעשית פחם.",
    "en": "As written, one who extinguishes out of fear or for a sick person is patur, one who does so to save the lamp is chayav, and Rabbi Yosi exempts in all cases except the wick. From the end clause that says chayav, the Gemara concludes the Mishnah follows Rabbi Yehudah. The first clause speaks of a sick person in danger, where it is actually permitted, and it says \"patur\" only because the end says \"chayav.\" On Rabbi Yosi's view they disagree: Ulla says he follows Rabbi Yehudah and holds that demolishing in order to rebuild elsewhere is not demolishing, while Rabbi Yochanan says he follows Rabbi Shimon and the Mishnah speaks of a wick that needs singeing, where one is fixing a utensil. And Rava infers this from the wording \"because he makes it charcoal,\" not \"because it becomes charcoal.\""
   },
