   "text": "שְׁלשָׁה דְבָרִים צָרִיךְ אָדָם לוֹמַר בְּתוֹךְ בֵּיתוֹ עֶרֶב שַׁבָּת עִם חֲשֵׁכָה. עִשַּׂרְתֶּם. עֵרַבְתֶּם. הַדְלִיקוּ אֶת הַנֵּר. סָפֵק חֲשֵׁכָה סָפֵק אֵין חֲשֵׁכָה, אֵין מְעַשְּׂרִין אֶת הַוַּדַּאי, וְאֵין מַטְבִּילִין אֶת הַכֵּלִים, וְאֵין מַדְלִיקִין אֶת הַנֵּרוֹת, אֲבָל מְעַשְּׂרִין אֶת הַדְּמַאי, וּמְעָרְבִין, וְטוֹמְנִין אֶת הַחַמִּין:",
   "gap": {
    "he": "לפי לשון המשנה, את שלשת הדברים אומרים עם חשכה, ובספק חשכה מערבין. הגמרא מקשה מהרישא לסיפא ומתרצת בשם רב: הרישא עוסקת בעירובי תחומין, והסיפא שמערבין בספק חשכה עוסקת בעירובי חצרות. רבא מסביר מדוע טומנין בספק חשכה אף על פי שמשחשכה אין טומנין בדבר שאינו מוסיף הבל, גזירה שמא ירתיח: סתם קדירות רותחות הן. ומהו בין השמשות נחלקו תנאים: לרבי יהודה משתשקע החמה עד שהכסיף העליון והשוה לתחתון, לרבי נחמיה כדי שיהלך אדם חצי מיל, ולרבי יוסי כהרף עין.",
    "en": "As written, the three things are said as darkness falls, and when it is doubtful whether it is dark one may still make an eruv. The Gemara points to a contradiction between the first and last clauses and answers in Rav's name: the first clause speaks of eruvei techumin, and the last, which allows an eruv when it may be dark, speaks of eruvei chatzeiros. Rava explains why one may insulate food when it may be dark even though after dark one may not insulate even in something that adds no heat, lest one bring it to a boil: ordinary pots are still boiling then. And what bein hashemashos is, the Tannaim dispute: for Rabbi Yehudah from sunset until the upper sky pales to match the lower, for Rabbi Nechemiah the time to walk half a mil, and for Rabbi Yosi the blink of an eye."
   },
