   "text": "כִּירָה שֶׁהִסִּיקוּהָ בְקַשׁ וּבִגְבָבָא, נוֹתְנִים עָלֶיהָ תַּבְשִׁיל. בְּגֶפֶת וּבְעֵצִים, לֹא יִתֵּן עַד שֶׁיִּגְרֹף, אוֹ עַד שֶׁיִּתֵּן אֶת הָאֵפֶר. בֵּית שַׁמַּאי אוֹמְרִים, חַמִּין אֲבָל לֹא תַבְשִׁיל. וּבֵית הִלֵּל אוֹמְרִים, חַמִּין וְתַבְשִׁיל. בֵּית שַׁמַּאי אוֹמְרִים, נוֹטְלִין אֲבָל לֹא מַחֲזִירִין. וּבֵית הִלֵּל אוֹמְרִים, אַף מַחֲזִירִין:",
   "gap": {
    "he": "לפי לשון המשנה, בגפת ובעצים לא יתן עד שיגרוף, ובית שמאי ובית הלל חולקים בחמין ותבשיל ובנטילה והחזרה. הגמרא קוראת \"לא יתן\" כלא יחזיר, ואילו להשהות מותר אף על פי שאינו גרוף. רבי מאיר בברייתא מציג את המחלוקת אחרת: בשהייה בית שמאי אוסרים הכל ובית הלל מתירים רק חמין, ותנא דידן סובר כרבי יהודה בחדא ופליג עליה בחדא. ומה מותר להשהות על כירה שאינה גרופה: לרבי יוחנן תבשיל שבישל כל צרכו אפילו מצטמק ויפה לו, ולשמואל ולרב נחמן מצטמק ויפה לו אסור. רב מצמצם את ההחזרה של בית הלל לעל גבה ולא לתוכה, ורב ששת מוסיף שמחזירין אפילו בשבת. ונחלקו אם מחזירין רק כשעודן בידו או אפילו אחר שהניחן על גבי קרקע, ולאביי הדבר תלוי בדעתו להחזיר.",
    "en": "As written, with pomace or wood one may not 'put' a pot on until the stove is swept, and Beis Shammai and Beis Hillel disagree about hot water versus cooked food and about returning a pot. The Gemara reads 'may not put' as 'may not return'; merely leaving a pot on is allowed even if the stove is not swept. Rabbi Meir in a baraisa frames the dispute differently: for leaving on, Beis Shammai allow nothing and Beis Hillel allow only hot water, and our Mishnah agrees with Rabbi Yehudah on one point and differs on another. What may be left on an unswept stove: for Rabbi Yochanan, fully cooked food even if it improves as it shrinks; for Shmuel and Rav Nachman, food that improves as it shrinks is forbidden. Rav limits Beis Hillel's returning to on top of the stove, not inside it, and Rav Sheshes adds that one returns even on Shabbos. And they dispute whether one may return only while the pot is still in hand or even after setting it on the ground, with Abaye making it depend on whether he intended to return it."
   },
