   "name": {
    "he": "מעשה אנשי טבריא",
    "en": "The people of Teverya"
   },
   "text": "מַעֲשֶׂה שֶׁעָשׂוּ אַנְשֵׁי טְבֶרְיָא וְהֵבִיאוּ סִלּוֹן שֶׁל צוֹנֵן לְתוֹךְ אַמָּה שֶׁל חַמִּין. אָמְרוּ לָהֶן חֲכָמִים, אִם בְּשַׁבָּת, כְּחַמִּין שֶׁהוּחַמּוּ בְשַׁבָּת, אֲסוּרִין בִּרְחִיצָה וּבִשְׁתִיָּה; בְּיוֹם טוֹב, כְּחַמִּין שֶׁהוּחַמּוּ בְיוֹם טוֹב, אֲסוּרִין בִּרְחִיצָה וּמֻתָּרִין בִּשְׁתִיָּה. מוּלְיָאר הַגָּרוּף, שׁוֹתִין הֵימֶנּוּ בְשַׁבָּת. אַנְטִיכִי, אַף עַל פִּי שֶׁגְּרוּפָה, אֵין שׁוֹתִין מִמֶּנָּה:",
   "gap": {
    "he": "לפי לשון המשנה, מעשה אנשי טבריא הוא דין בפני עצמו על צינור צונן בתוך אמת חמין, ואחריו מוליאר ואנטיכי. הגמרא קוראת את המעשה כחלק מויכוח החכמים עם רבי יוסי על סודרין, ורבי יוסי משיב שחמי טבריא תולדות האור הם. רב איקא בר חנניא מעמיד את הרחיצה האסורה בשטיפת כל הגוף. מוליאר הגרוף הוא שמים מבפנים וגחלים מבחוץ. ונחלקו מהו אנטיכי: לרבה בי כירי, ולרב נחמן בר יצחק בי דודי, והברייתא כרב נחמן שאסורה מפני שנחושתה מחממתה.",
    "en": "As written, the episode of the people of Teverya is a ruling of its own about a pipe of cold water run through a channel of hot springs, followed by the muliar and the antichi. The Gemara reads the episode as part of the Chachamim's argument with Rabbi Yosei about the hot cloths, and Rabbi Yosei answers that the Teverya springs count as derivatives of fire. Rav Ika bar Chananya sets the forbidden washing as rinsing the whole body. A swept muliar is one with water inside and coals outside. And they dispute what an antichi is: for Rabbah a 'bei kirei', for Rav Nachman bar Yitzchak a 'bei dudei', and the baraisa agrees with Rav Nachman that it is forbidden because its copper keeps it hot."
   },
