   "name": {
    "he": "המיחם שפינהו",
    "en": "A kettle that was moved"
   },
   "text": "הַמֵּחַם שֶׁפִּנָּהוּ, לֹא יִתֵּן לְתוֹכוֹ צוֹנֵן בִּשְׁבִיל שֶׁיֵּחַמּוּ, אֲבָל נוֹתֵן הוּא לְתוֹכוֹ אוֹ לְתוֹךְ הַכּוֹס כְּדֵי לְהַפְשִׁירָן. הָאִלְפָּס וְהַקְּדֵרָה שֶׁהֶעֱבִירָן מְרֻתָּחִין, לֹא יִתֵּן לְתוֹכָן תְּבָלִין, אֲבָל נוֹתֵן הוּא לְתוֹךְ הַקְּעָרָה אוֹ לְתוֹךְ הַתַּמְחוּי. רַבִּי יְהוּדָה אוֹמֵר, לַכֹּל הוּא נוֹתֵן, חוּץ מִדָּבָר שֶׁיֶּשׁ בּוֹ חֹמֶץ וְצִיר:",
   "gap": {
    "he": "לפי לשון המשנה, במיחם שפינהו לא יתן צונן כדי שיחמו אבל נותן כדי להפשירן, ובאילפס וקדרה לא יתן תבלין, ורבי יהודה מתיר לכל חוץ מחומץ וציר. רב אדא בר מתנא קורא: מיחם שפינה ממנו מים חמין, מים מועטים אסור ומרובים מותר; אביי קורא: מיחם שיש בו מים חמין, ומיחם שפינה ממנו מים אסור כלל משום שמצרף, כרבי יהודה. רב מתיר רק שיעור להפשיר, ושמואל אפילו שיעור לצרף. הברייתא מראה שרבי יהודה קאי ארישא ולקולא, אפילו לאילפסין וקדרות רותחות. ונחלקו אם מלח כתבלין: לרב יוסף מלח מתבשלת רק בכלי ראשון, ולרבי חייא אינה כתבלין, אם משום שמתבשלת אפילו בכלי שני ואם משום שאינה מתבשלת אפילו בכלי ראשון.",
    "en": "As written, into a kettle that was moved one may not put cold water to heat it but may to take off the chill, into a hot pot one may not put spices, and Rabbi Yehudah allows everything except vinegar and brine. Rav Adda bar Masna reads it as a kettle emptied of hot water, where a little water is forbidden and a lot is allowed; Abaye reads it as a kettle still holding hot water, while an emptied kettle may get no water at all because it would temper the metal, following Rabbi Yehudah. Rav allows only an amount that takes off the chill, and Shmuel even an amount that would temper the metal. The baraisa shows that Rabbi Yehudah refers to the first clause and is lenient, even for boiling pots. And they dispute whether salt is like spices: for Rav Yosef salt cooks only in a first vessel, and Rabbi Chiya's baraisa says it is not like spices, either because it cooks even in a second vessel or because it does not cook even in a first."
   },
