   "name": {
    "he": "טומנין בשלחין",
    "en": "Wrapping in hides and fleece"
   },
   "text": "טוֹמְנִין בִּשְׁלָחִין, וּמְטַלְטְלִין אוֹתָן, בְּגִזֵּי צֶמֶר, וְאֵין מְטַלְטְלִין אוֹתָן. כֵּיצַד הוּא עוֹשֶׂה, נוֹטֵל אֶת הַכִּסּוּי וְהֵן נוֹפְלוֹת. רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר, קֻפָּה, מַטָּהּ עַל צִדָּהּ וְנוֹטֵל, שֶׁמָּא יִטֹּל וְאֵינוֹ יָכֹל לְהַחֲזִיר. וַחֲכָמִים אוֹמְרִים, נוֹטֵל וּמַחֲזִיר. לֹא כִסָּהוּ מִבְּעוֹד יוֹם, לֹא יְכַסֶּנּוּ מִשֶּׁתֶּחְשָׁךְ. כִּסָּהוּ וְנִתְגַּלָּה, מֻתָּר לְכַסּוֹתוֹ. מְמַלֵּא אֶת הַקִּיתוֹן וְנוֹתֵן לְתַחַת הַכַּר, אוֹ תַחַת הַכָּסֶת:",
   "gap": {
    "he": "לפי לשון המשנה, טומנין בשלחין ומטלטלין אותן, בגיזי צמר ואין מטלטלין, ורבי אלעזר בן עזריה וחכמים חולקים בקופה. נחלקו אם שלחין הן דווקא של בעל הבית או אפילו של אומן, שרבי יוסי היה שלחא ואמר הביאו שלחין ונשב עליהן. רבא מעמיד את איסור הגיזים כשלא ייחדן להטמנה, ורבינא בגיזים של הפתק. רב מגביל את המחלוקת: אם נתקלקלה הגומא הכל מודים שאסור להחזיר. והמחלוקת היא אם חוששים שמא נתקלקלה. שמואל מתיר להטמין צונן, ואביי מוסיף שמהמשנה היינו מתירים רק דבר שאין דרכו להטמין.",
    "en": "As written, one may wrap in hides and move them, in shorn wool and not move it, and Rabbi Elazar ben Azaryah and the Chachamim disagree about the basket. They dispute whether the hides are only a householder's or even a craftsman's, since Rabbi Yosei, a tanner, would say bring hides and we will sit on them. Rava sets the ban on moving the wool where it was not designated for wrapping, and Ravina where it is stored merchandise. Rav limits the dispute: if the hollow collapsed, all agree one may not return the pot. The dispute is whether we worry that it collapsed. Shmuel allows wrapping cold food, and Abaye adds that from the Mishnah alone we would allow only something not usually wrapped."
   },
