     "q": "לְעוֹלָם דְּלָא נִתְקַלְקְלָה, וְהָכָא בְּחוֹשְׁשִׁין קָמִיפַּלְגִי. מָר סָבַר חוֹשְׁשִׁין שֶׁמָּא נִתְקַלְקְלָה הַגּוּמָּא, וּמָר סָבַר אֵין חוֹשְׁשִׁין.",
