   "name": {
    "he": "חמור במרדעת",
    "en": "A donkey with a saddle cloth"
   },
   "text": "חֲמוֹר יוֹצֵא בְמַרְדַּעַת, בִּזְמַן שֶׁהִיא קְשׁוּרָה לוֹ. זְכָרִים יוֹצְאִין לְבוּבִין. רְחֵלוֹת יוֹצְאוֹת שְׁחוּזוֹת, כְּבוּלוֹת וּכְבוּנוֹת. הָעִזִּים יוֹצְאוֹת צְרוּרוֹת. רַבִּי יוֹסֵי אוֹסֵר בְּכֻלָּן, חוּץ מִן הָרְחֵלִין הַכְּבוּנוֹת. רַבִּי יְהוּדָה אוֹמֵר, עִזִּים יוֹצְאוֹת צְרוּרוֹת לְיַבֵּשׁ, אֲבָל לֹא לְחָלָב:",
   "gap": {
    "he": "לפי לשון המשנה, חמור יוצא במרדעת כשהיא קשורה לו, ורבי יוסי ורבי יהודה חולקים בעזים צרורות. שמואל מעמיד בקשורה לו מערב שבת, ורב נחמן מדייק כן מן המשנה של אין החמור יוצא. נחלקו מהו לבובין: לרב הונא תותרי, לעולא עור כנגד לבם מפני זאבים, ולרב נחמן בר יצחק עור תחת זכרותן, כפי שמוכח מן הרחלים השחוזות שבסיפא. כבולות הן שמכבלין את האליה למטה, וכבונות שמכבנין אותן למילת. ובהלכה נחלקו רב ושמואל, אם כרבי יהודה ולייבש מותר, או כרבי יוסי ואחד זה ואחד זה אסור.",
    "en": "As written, a donkey goes out with a saddle cloth when it is tied on, and Rabbi Yosei and Rabbi Yehudah disagree about goats with tied udders. Shmuel sets it where the cloth was tied on before Shabbos, and Rav Nachman infers this from the Mishnah's clause that a donkey may not go out with an untied cloth. They dispute what levuvin means: for Rav Huna 'tusarei', for Ulla a skin tied over the heart against wolves, and for Rav Nachman bar Yitzchak a skin tied under the male organ, as proven from the shechuzos ewes in the next clause. Kevulos means the tail is tied down, and kevunos means they are wrapped for fine wool. On the halacha Rav and Shmuel disagree, whether like Rabbi Yehudah so that drying is allowed, or like Rabbi Yosei so that both are forbidden."
   },
