   "text": "אֵין חֲמוֹר יוֹצֵא בְמַרְדַּעַת בִּזְמַן שֶׁאֵינָהּ קְשׁוּרָה לוֹ, וְלֹא בְזוֹג, אַף עַל פִּי שֶׁהוּא פָקוּק, וְלֹא בְסֻלָּם שֶׁבְּצַוָּארוֹ, וְלֹא בִרְצוּעָה שֶׁבְּרַגְלוֹ. וְאֵין הַתַּרְנְגוֹלִין יוֹצְאִין בְּחוּטִין, וְלֹא בִרְצוּעוֹת שֶׁבְּרַגְלֵיהֶם. וְאֵין הַזְּכָרִים יוֹצְאִין בַּעֲגָלָה שֶׁתַּחַת הָאַלְיָה שֶׁלָּהֶן. וְאֵין הָרְחֵלִים יוֹצְאוֹת חֲנוּנוֹת. וְאֵין הָעֵגֶל יוֹצֵא בְגִימוֹן. וְלֹא פָרָה בְּעוֹר הַקֻּפָּר, וְלֹא בִרְצוּעָה שֶׁבֵּין קַרְנֶיהָ. פָּרָתוֹ שֶׁל רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה הָיְתָה יוֹצְאָה בִרְצוּעָה שֶׁבֵּין קַרְנֶיהָ, שֶׁלֹּא בִרְצוֹן חֲכָמִים:",
   "gap": {
    "he": "לפי לשון המשנה, החמור אינו יוצא בסולם שבצוארו, והרחלים אינן יוצאות חנונות, והעגל לא בגימון, והפרה לא ברצועה שבין קרניה, ופרתו של רבי אלעזר בן עזריה יצאה כך. סולם שבצוארו הוא בי לועא, שעושים לבהמה שיש לה מכה כדי שלא תחכך בה. נחלקו מהו חנונות: רב אחא בר עולא ורב פפא בר שמואל מפרשים עזק של שמן לחמם אותה, ורב הונא קיסם מעץ יחנון בחוטמה כדי שתתעטש. עגל בגימון הוא בר נירא. ברצועה שבין קרניה, לרב אסור בין לנוי בין לשמר, ולשמואל לנוי אסור ולשמר מותר. והברייתא מבארת שהפרה לא היתה שלו אלא של שכנתו, ונקראת על שמו משום שלא מיחה בה.",
    "en": "As written, a donkey may not go out with a ladder on its neck, ewes may not go out chanunos, a calf not with a gimon, a cow not with a strap between its horns, and Rabbi Elazar ben Azaryah's cow went out that way. The ladder on the neck is a 'bei lo'a', made for an animal with a wound so it cannot scratch it. They dispute what chanunos means: Rav Acha bar Ulla and Rav Pappa bar Shmuel explain it as an oil-soaked wad to warm the ewe, and Rav Huna as a sliver of the yachnun tree in its nose so that it sneezes. A calf with a gimon is one under a small yoke. A strap between the horns, for Rav, is forbidden whether for beauty or for restraint, and for Shmuel forbidden for beauty and allowed for restraint. And a baraisa explains that the cow was not his but his neighbor's, called by his name because he did not protest."
   },
