   "text": "לֹא יֵצֵא הָאִישׁ לֹא בְסַיִף, וְלֹא בְקֶשֶׁת, וְלֹא בִתְרִיס, וְלֹא בְאַלָּה, וְלֹא בְרֹמַח. וְאִם יָצָא, חַיָּב חַטָּאת. רַבִּי אֱלִיעֶזֶר אוֹמֵר, תַּכְשִׁיטִין הֵן לוֹ. וַחֲכָמִים אוֹמְרִים, אֵינָן אֶלָּא לִגְנַאי, שֶׁנֶּאֱמַר (ישעיה ב) וְכִתְּתוּ חַרְבוֹתָם לְאִתִּים וַחֲנִיתוֹתֵיהֶם לְמַזְמֵרוֹת, לֹא יִשָּׂא גּוֹי אֶל גּוֹי חֶרֶב וְלֹא יִלְמְדוּ עוֹד מִלְחָמָה. בִּירִית, טְהוֹרָה, וְיוֹצְאִין בָּהּ בְּשַׁבָּת. כְּבָלִים, טְמֵאִין, וְאֵין יוֹצְאִין בָּהֶם בְּשַׁבָּת:",
   "gap": {
    "he": "לפי לשון המשנה, האיש אינו יוצא בכלי זין, רבי אליעזר אומר שתכשיטים הם לו, וחכמים מביאים ראיה מן הפסוק שיתבטלו לעתיד; בירית מותרת וכבלים אסורים. הגמרא מבארת שאלה היא קולפא, אלה. לשאלה למה יתבטלו לימות המשיח אם תכשיטים הם, לשון אחד ברבי אליעזר עונה שלא יהיה בהם צורך, ולשון אחר שאף לימות המשיח אינם בטלים. טעמו של רבי אליעזר הוא הפסוק ׳חגור חרבך על ירך גבור הודך והדרך׳. רב יהודה מבאר שבירית עומדת תחת האצעדה. ובבירית וכבלים נחלקו: לרבין בירית באחת וכבלים בשתים, ולרב הונא שתיהן בשתי רגליים, וכשמטילים שלשלת ביניהן נעשו כבלים.",
    "en": "As written, a man may not go out with weapons; Rabbi Eliezer says they are ornaments for him, and the Chachamim cite the verse that they will be abolished; a garter is permitted and ankle chains are not. The Gemara glosses the alah as a club. To the question why they will be abolished in the days of Mashiach if they are ornaments, one version of Rabbi Eliezer answers that there will be no need for them, and another that even then they will not be abolished. Rabbi Eliezer's source is the verse \"Gird your sword on your thigh, mighty one, your glory and your splendor.\" Rav Yehuda explains that the garter sits in place of an ankle band. On garter and chains they disagree: Ravin says a garter is on one leg and chains on two, and Rav Huna says both are on two legs, and once a chain is put between them they become kevalim."
   },
