   "text": "יוֹצְאָה בְסֶלַע שֶׁעַל הַצִּינִית. הַבָּנוֹת קְטַנּוֹת יוֹצְאוֹת בְּחוּטִין וַאֲפִלּוּ בְקִסְמִין שֶׁבְּאָזְנֵיהֶם. עַרְבִיּוֹת יוֹצְאוֹת רְעוּלוֹת, וּמָדִיּוֹת פְּרוּפוֹת, וְכָל אָדָם, אֶלָּא שֶׁדִּבְּרוּ חֲכָמִים בַּהֹוֶה:",
   "gap": {
    "he": "לפי לשון המשנה, אשה יוצאת בסלע שעל הצינית, הבנות יוצאות בחוטים ובקיסמים שבאזניהן, וערביות ומדיות בלבושן. הגמרא מבארת שצינית היא בת ארעא, יבלת ברגל. ולמה דווקא סלע, אביי מסיק שכל תכונותיו מועילות: קשיותו, חלודתו וצורתו. ומאביו של שמואל, שלא הניח לבנותיו לצאת בחוטים, עולה שבנותיו היו בחוטים צבעונים, ומכאן שהמשנה מתירה רק חוטים שאינם צבעונים.",
    "en": "As written, a woman may go out with a sela coin on a tzinis, girls may go out with threads and even wood chips in their ears, and Arab and Median women in their usual dress. The Gemara explains that a tzinis is a bas ara, a corn on the foot. As for why a sela specifically, Abaye concludes that all its qualities help: its hardness, its rust and its image. And from Shmuel's father, who did not let his daughters go out with threads, it emerges that his daughters' threads were colored, so the Mishnah permits only threads that are not colored."
   },
