   "text": "הַקִּטֵּעַ יוֹצֵא בְקַב שֶׁלּוֹ, דִּבְרֵי רַבִּי מֵאִיר. וְרַבִּי יוֹסֵי אוֹסֵר. וְאִם יֶשׁ לוֹ בֵית קִבּוּל כְּתוּתִים, טָמֵא. סָמוֹכוֹת שֶׁלּוֹ, טְמֵאִין מִדְרָס, וְיוֹצְאִין בָּהֶן בְּשַׁבָּת, וְנִכְנָסִין בָּהֶן בָּעֲזָרָה. כִּסֵּא וְסָמוֹכוֹת שֶׁלּוֹ, טְמֵאִין מִדְרָס, וְאֵין יוֹצְאִין בָּהֶן בְּשַׁבָּת, וְאֵין נִכְנָסִין בָּהֶן בָּעֲזָרָה. אַנְקַטְמִין טְהוֹרִין, וְאֵין יוֹצְאִין בָּהֶן:",
   "gap": {
    "he": "לפי לשון המשנה, הקיטע יוצא בקב שלו לרבי מאיר ורבי יוסי אוסר, ואם יש לו בית קיבול כתיתין טמא, וכן דיני סמוכות, כסא ולוקטמין. בנוסח המשנה נחלקו: שמואל ורב הונא שנו ׳אין הקיטע׳, כלומר רבי מאיר אוסר, ורב הורה להפוך כנוסח שלנו, ושמואל ורב הונא חזרו בהם. בבית קיבול כתיתין נחלקו: לאביי טמא טומאת מת ואינו טמא מדרס, ולרבא אף טמא מדרס. ובלוקטמין נחלקו שלושה אמוראים: מסגרת משא של חמור, קישרי או פרמי.",
    "en": "As written, the amputee may go out on his wooden leg according to Rabbi Meir and Rabbi Yosi forbids, and if it has a cavity for padding it is tamei, followed by rules for leg supports, a chair and lukatmin. On the text of the Mishnah they disagree: Shmuel and Rav Huna taught \"the amputee may not,\" so Rabbi Meir forbids, and Rav directed it to be reversed to our text, and Shmuel and Rav Huna retracted. On the cavity for padding they disagree: Abaye says it is tamei with corpse tumah but not midras, and Rava says it is tamei with midras as well. And three amoraim define lukatmin: a donkey's pack frame, kishrei, or pramei."
   },
