   "text": "הַבָּנִים יוֹצְאִין בִּקְשָׁרִים, וּבְנֵי מְלָכִים בְּזוֹגִין. וְכָל אָדָם, אֶלָּא שֶׁדִּבְּרוּ חֲכָמִים בַּהֹוֶה:",
   "gap": {
    "he": "לפי לשון המשנה, הבנים יוצאים בקשרים ובני מלכים בזוגין, וכל אדם, אלא שדיברו חכמים בהווה. הגמרא שואלת למה דווקא בנים וקטנים, ומבארת שקשרים הם רצועה ממנעל ימין שקושרים על שמאל של בן שמתגעגע על אביו. ובבני מלכים בזוגין נחלקו: לרבי אושעיא המשנה כרבי שמעון שכל ישראל בני מלכים, ולרבא מדובר בזוג ארוג בבגדו, ודברי הכל.",
    "en": "As written, boys may go out with knots and princes with bells, and so may anyone, but the Chachamim spoke of the usual case. The Gemara asks why boys and why young ones specifically, and explains that the knots are a strap from the right shoe tied on the left arm of a boy who pines for his father. On princes with bells they disagree: Rabbi Oshaya says the Mishnah follows Rabbi Shimon, that all Jews are princes, and Rava says it speaks of a bell woven into the garment, and all agree."
   },
