   "text": "יוֹצְאִין בְּבֵיצַת הַחַרְגּוֹל, וּבְשֵׁן שׁוּעָל, וּבְמַסְמֵר מִן הַצָּלוּב, מִשּׁוּם רְפוּאָה, דִּבְרֵי רַבִּי מֵאִיר. וַחֲכָמִים אוֹמְרִים, אַף בְּחֹל אָסוּר, מִשּׁוּם דַּרְכֵי הָאֱמוֹרִי:",
   "gap": {
    "he": "לפי לשון המשנה, רבי מאיר מתיר לצאת בביצת החרגול, בשן שועל ובמסמר מן הצלוב משום רפואה, וחכמים אוסרים אף בחול משום דרכי האמורי. הגמרא מפרטת את הרפואה: ביצת החרגול לכאב אוזן, שן שועל חי למי שישן יותר מדי ושל מת למי שאינו ישן, ומסמר מן הצלוב לנפיחות. ואביי ורבא קובעים שכל דבר שיש בו משום רפואה אין בו משום דרכי האמורי, כך שהמחלוקת תלויה בשאלה אם יש בהם רפואה.",
    "en": "As written, Rabbi Meir permits going out with a locust egg, a fox tooth and a nail from a crucifixion as a remedy, and the Chachamim forbid it even on weekdays as Amorite practice. The Gemara spells out the remedies: a locust egg for earache, a tooth from a live fox for one who sleeps too much and from a dead fox for one who cannot sleep, and a crucifixion nail for swelling. And Abaye and Rava set the rule that anything that works as a remedy is not Amorite practice, so the dispute turns on whether these are real remedies."
   },
