   "text": "כְּלָל גָּדוֹל אָמְרוּ בַשַּׁבָּת. כָּל הַשּׁוֹכֵחַ עִקַּר שַׁבָּת וְעָשָׂה מְלָאכוֹת הַרְבֵּה בְשַׁבָּתוֹת הַרְבֵּה, אֵינוֹ חַיָּב אֶלָּא חַטָּאת אֶחָת. הַיּוֹדֵעַ עִקַּר שַׁבָּת וְעָשָׂה מְלָאכוֹת הַרְבֵּה בְּשַׁבָּתוֹת הַרְבֵּה, חַיָּב עַל כָּל שַׁבָּת וְשַׁבָּת. הַיּוֹדֵעַ שֶׁהוּא שַׁבָּת וְעָשָׂה מְלָאכוֹת הַרְבֵּה בְּשַׁבָּתוֹת הַרְבֵּה, חַיָּב עַל כָּל אַב מְלָאכָה וּמְלָאכָה. הָעוֹשֶׂה מְלָאכוֹת הַרְבֵּה מֵעֵין מְלָאכָה אַחַת, אֵינוֹ חַיָּב אֶלָּא חַטָּאת אֶחָת:",
   "gap": {
    "he": "לפי לשון המשנה, השוכח עיקר שבת חייב חטאת אחת בלבד, ולא נאמר מי הוא. הגמרא מדייקת שאם היודע שהוא שבת היה מי שלא שכח כלל, היה התנא שונה את החידוש הגדול יותר, ולכן המשנה עוסקת במי שהכיר ולבסוף שכח. רב ושמואל אומרים שגם תינוק שנשבה וגר שנתגייר בין הגויים הם כהכיר ולבסוף שכח וחייבים, ורבי יוחנן וריש לקיש פוטרים אותם. רב נחמן מסביר את ההבדל בין חיוב על כל שבת לחיוב על כל מלאכה: הקרבן בא על השגגה, ובזה שגגה אחת ובזה שגגות הרבה. והברייתא מלמדת מהו מעין מלאכה אחת: הזורע, הזומר, הנוטע, המבריך והמרכיב כולם מלאכה אחת.",
    "en": "As written, one who forgot the essence of Shabbos brings only one chatas, and the Mishnah does not say who he is. The Gemara infers from the wording that if the one who knows it is Shabbos had never forgotten at all, the Mishnah would have taught the bigger chiddush, so the Mishnah is dealing with one who knew and later forgot. Rav and Shmuel say a child captured among non-Jews and a convert among non-Jews are also like one who knew and forgot, and are liable; Rabbi Yochanan and Reish Lakish exempt them. Rav Nachman explains the difference between liability per Shabbos and liability per melachah: the korban comes for the shegagah, and here there is one shegagah while there there are many. And the baraisa shows what 'many melachos of one kind' means: sowing, pruning, planting, layering and grafting are all one melachah."
   },
