   "text": "וְעוֹד כְּלָל אַחֵר אָמְרוּ. כָּל הַכָּשֵׁר לְהַצְנִיעַ וּמַצְנִיעִין כָּמוֹהוּ וְהוֹצִיאוֹ בְשַׁבָּת, חַיָּב עָלָיו חַטָּאת, וְכָל שֶׁאֵינוֹ כָשֵׁר לְהַצְנִיעַ וְאֵין מַצְנִיעִין כָּמוֹהוּ וְהוֹצִיאוֹ בְשַׁבָּת, אֵינוֹ חַיָּב אֶלָּא הַמַּצְנִיעוֹ:",
   "gap": {
    "he": "לפי לשון המשנה, כל דבר שראוי להצניע ומצניעים כמותו חייבים על הוצאתו, ולא נאמר מה יוצא מן הכלל. רב פפא אומר שהכלל בא להוציא דם נדה, ומר עוקבא אומר שהוא בא להוציא עצי אשרה. רבי יוסי בר חנינא אומר שהרישא אינה כרבי שמעון, הסובר שהשיעורים נאמרו רק למצניעיהם. ורבי אלעזר אומר שהסיפא אינה כרבי שמעון בן אלעזר, הסובר שאם אחד הצניע דבר שאין מצניעים כמותו ובא אחר והוציאו, השני חייב במחשבתו של הראשון.",
    "en": "As written, anything fit to be stored and that people store makes one liable for carrying it out, and the Mishnah does not say what the rule excludes. Rav Papa says the rule comes to exclude niddah blood, and Mar Ukva says it comes to exclude the wood of an asheirah. Rabbi Yosi bar Chanina says the first clause is not like Rabbi Shimon, who holds the measures were stated only for those who store them. And Rabbi Elazar says the last clause is not like Rabbi Shimon ben Elazar, who holds that if one person stored something people do not store and another carried it out, the second is liable through the first one's intent."
   },
