   "text": "אֲדָמָה, כְּחוֹתַם הַמַּרְצוּפִים, דִּבְרֵי רַבִּי עֲקִיבָא. וַחֲכָמִים אוֹמְרִים, כְּחוֹתַם הָאִגְּרוֹת. זֶבֶל וְחֹל הַדַּק, כְּדֵי לְזַבֵּל קֶלַח שֶׁל כְּרוּב, דִּבְרֵי רַבִּי עֲקִיבָא. וַחֲכָמִים אוֹמְרִים, כְּדֵי לְזַבֵּל כְּרֵשָׁא. חֹל הַגַּס, כְּדֵי לִתֵּן עַל מְלֹא כַף סִיד. קָנֶה, כְּדֵי לַעֲשׂוֹת קֻלְמוֹס. וְאִם הָיָה עָב אוֹ מְרֻסָּס, כְּדֵי לְבַשֵּׁל בוֹ בֵיצָה קַלָּה שֶׁבַּבֵּיצִים, טְרוּפָה וּנְתוּנָה בָאִלְפָּס:",
   "gap": {
    "he": "לפי לשון המשנה, חול הגס כדי לתת על מלא כף סיד, קנה כדי לעשות קולמוס, וקנה עבה כדי לבשל ביצה קלה, בלי פירוש. הברייתא מפרשת כף סיד ככף של סיידין. מי סובר שחול משביח את הסיד? רב חסדא אומר רבי יהודה היא, ורבא אומר אפילו רבנן, כי קלקולו זהו תיקונו. הברייתא מגדירה קולמוס המגיע לקשרי אצבעותיו. רב ששת מפרש ביצה קלה כביצת תרנגולת, הקלה לבשל מכולן. ורב נחמן מסביר שהשיעור הוא כגרוגרת מביצה קלה, כשאר שיעורי שבת.",
    "en": "As written, coarse sand is enough to put on a ladle of lime, a reed enough to make a quill, and a thick reed enough to cook a 'light egg', without explanation. The baraisa explains the ladle as a plasterer's ladle. Who holds that sand improves lime? Rav Chisda says it is Rabbi Yehudah, and Rava says even the Rabbanan, because spoiling it is what fixes it. The baraisa defines a quill that reaches the joints of one's fingers. Rav Sheshes explains the light egg as a hen's egg, the easiest to cook. And Rav Nachman explains that the measure is a dried fig's worth of a light egg, like the other measures of Shabbos."
   },
