   "name": {
    "he": "עצם, זכוכית וצרור",
    "en": "Bone, glass and pebble"
   },
   "text": "עֶצֶם, כְּדֵי לַעֲשׂוֹת תַּרְוָד. רַבִּי יְהוּדָה אוֹמֵר, כְּדֵי לַעֲשׂוֹת מִמֶּנּוּ חָף. זְכוּכִית, כְּדֵי לִגְרֹר בּוֹ רֹאשׁ הַכַּרְכָּר. צְרוֹר אוֹ אֶבֶן, כְּדֵי לִזְרֹק בְּעוֹף. רַבִּי אֱלִיעֶזֶר בַּר יַעֲקֹב אוֹמֵר, כְּדֵי לִזְרֹק בִּבְהֵמָה:",
   "gap": {
    "he": "לפי לשון המשנה, רבי יהודה משער עצם כדי לעשות חף, ורבי אלעזר בן יעקב משער צרור כדי לזרוק בבהמה. הגמרא מקשה שאם כן שיעור רבי יהודה גדול משל חכמים, ועולא מפרש חף כחפי פותחת, שן של מפתח. רבי יוחנן מצמצם את דברי רבי אלעזר בן יעקב לאבן שהבהמה מרגישת בה. והברייתא נותנת את שיעורו: משקל עשרה זוז.",
    "en": "As written, Rabbi Yehudah measures bone by enough to make a 'chaf', and Rabbi Elazar ben Yaakov measures a pebble by enough to throw at an animal. The Gemara objects that Rabbi Yehudah's measure would then be larger than the Chachamim's, and Ulla explains chaf as the teeth of a key. Rabbi Yochanan limits Rabbi Elazar ben Yaakov's words to a stone the animal feels. And the baraisa gives its measure: the weight of ten zuz."
   },
