   "text": "מִנַּיִן לִסְפִינָה שֶׁהִיא טְהוֹרָה, שֶׁנֶּאֱמַר (משלי ל) דֶּרֶךְ אֳנִיָּה בְלֶב יָם. מִנַּיִן לַעֲרוּגָה שֶׁהִיא שִׁשָּׁה עַל שִׁשָּׁה טְפָחִים שֶׁזּוֹרְעִין בְּתוֹכָהּ חֲמִשָּׁה זֵרְעוֹנִין, אַרְבָּעָה בְאַרְבַּע רוּחוֹת הָעֲרוּגָה וְאֶחָד בָּאֶמְצַע, שֶׁנֶּאֱמַר (ישעיה סא) כִּי כָאָרֶץ תּוֹצִיא צִמְחָהּ וּכְגַנָּה זֵרוּעֶיהָ תַצְמִיחַ, זַרְעָהּ לֹא נֶאֱמַר, אֶלָּא זֵרוּעֶיהָ:",
   "gap": {
    "he": "לפי לשון המשנה, ספינה טהורה מן הפסוק 'דרך אניה בלב ים', וערוגה של שישה על שישה מקבלת חמישה זרעונים. הגמרא מפרשת שהספינה טהורה כמו הים, וחנניה בברייתא לומד משק שאינו מיטלטל מלא, והנפקא מינה היא ספינה של חרס. חמישה מינים בשישה טפחים מותרים משום שקים להו לרבנן שאינם יונקים זה מזה. רב אסי מבאר ששישה הטפחים הם בתוך הערוגה חוץ מגבוליה. ורב ושמואל חלוקים היכן הערוגה: לרב בחורבה, לשמואל בין הערוגות.",
    "en": "As written, a ship is tahor from the pasuk 'the way of a ship in the heart of the sea', and a six by six bed holds five kinds of seeds. The Gemara explains that the ship is tahor like the sea itself, while Chananya in a baraisa learns from a sack, which is not carried when full, and the practical difference is an earthenware ship. Five kinds in six tefachim are allowed because the Rabbis knew they do not draw from each other. Rav Assi explains that the six tefachim are the inside of the bed, not counting its borders. And Rav and Shmuel disagree where the bed is: for Rav in a ruin, for Shmuel among other beds."
   },
