   "gap": {
    "he": "לפי לשון המשנה, המוציא ביד, בחיק או על כתפו חייב שכן משא בני קהת, ושלא כדרך המוציאין פטור. רבי אלעזר לומד מכאן שהמוציא משאוי למעלה מעשרה טפחים חייב, שכך נשאו בני קהת. רב משום רבי חייא אומר שהמוציא משוי על ראשו פטור, ואם אנשי הוצל עושים כן בטלה דעתם אצל כל אדם. ו'פונדתו ופיה למטה' שבמשנה הוא דעת חכמים נגד רבי יהודה המחייב: זה מדמה ללאחריו ובא לו לאחריו, וזה מדמה ללאחר ידו ורגלו.",
    "en": "As written, one who carries in his hand, his bosom or on his shoulder is liable, as that was how the sons of Kehas carried, and an unusual way is exempt. Rabbi Elazar learns from this that one who carries a load above ten tefachim is liable, since that is how the sons of Kehas carried. Rav in the name of Rabbi Chiya says one who carries a load on his head is exempt, and if the people of Hutzal do so, their practice is set aside against everyone else's. And 'in his money belt with its opening downward' in the Mishnah is the view of the Chachamim against Rabbi Yehudah, who holds liable: one compares it to intending behind and it landing behind, the other to the back of the hand or the foot."
   },
