   "text": "הַמִּתְכַּוֵּן לְהוֹצִיא לְפָנָיו וּבָא לוֹ לְאַחֲרָיו, פָּטוּר, לְאַחֲרָיו וּבָא לוֹ לְפָנָיו, חַיָּב. בֶּאֱמֶת אָמְרוּ, הָאִשָּׁה הַחוֹגֶרֶת בְּסִינָר בֵּין מִלְּפָנֶיהָ וּבֵין מִלְּאַחֲרֶיהָ חַיֶּבֶת, שֶׁכֵּן רָאוּי לִהְיוֹת חוֹזֵר. רַבִּי יְהוּדָה אוֹמֵר, אַף מְקַבְּלֵי פִתְקִין:",
   "gap": {
    "he": "לפי לשון המשנה, נתכוון לפניו ובא לו לאחריו פטור, ולאחריו ובא לו לפניו חייב, בלי טעם. רבא מבאר: בראשון נתכוון לשמירה מעולה ועלתה בידו שמירה פחותה, ובשני להפך. על הדיוק שבין הרישא לסיפא, רבי אלעזר אומר שמי ששנה זו לא שנה זו, ורב אשי אומר שהמשנה 'לא מיבעיא' קאמר. והגמרא מסכמת שלאחריו ובא לו לאחריו לדברי הכל חייב. 'באמת אמרו' פירושו הלכה, וטעם רבי יהודה במקבלי פתקין הוא שכך עושים לבלרי המלכות.",
    "en": "As written, intending in front and it landing behind is exempt, and intending behind and it landing in front is liable, with no reason given. Rava explains: in the first he intended better safekeeping and got lesser, and in the second the reverse. On the inference that sets the first clause against the last, Rabbi Elazar says the two clauses come from different Tannaim, and Rav Ashi says the Mishnah speaks in a 'not only this but even that' style. And the Gemara concludes that intending behind and it landing behind is liable according to all. 'In truth they said' means it is halachah, and Rabbi Yehudah's reason for the note carriers is that the royal scribes do so."
   },
