   "text": "הַמּוֹצִיא כִכָּר לִרְשׁוּת הָרַבִּים, חַיָּב. הוֹצִיאוּהוּ שְׁנַיִם, פְּטוּרִין. לֹא יָכֹל אֶחָד לְהוֹצִיאוֹ וְהוֹצִיאוּהוּ שְׁנַיִם, חַיָּבִים. וְרַבִּי שִׁמְעוֹן פּוֹטֵר. הַמּוֹצִיא אֳכָלִין פָּחוֹת מִכַּשִּׁעוּר בִּכְלִי, פָּטוּר אַף עַל הַכְּלִי, שֶׁהַכְּלִי טְפֵלָה לוֹ. אֶת הַחַי בַּמִּטָּה, פָּטוּר אַף עַל הַמִּטָּה, שֶׁהַמִּטָּה טְפֵלָה לוֹ. אֶת הַמֵּת בַּמִּטָּה, חַיָּב. וְכֵן כַּזַּיִת מִן הַמֵּת וְכַזַּיִת מִן הַנְּבֵלָה וְכָעֲדָשָׁה מִן הַשֶּׁרֶץ, חַיָּב. וְרַבִּי שִׁמְעוֹן פּוֹטֵר:",
   "gap": {
    "he": "לפי לשון המשנה, שנים שהוציאו ככר פטורים, ואם לא יכול אחד חייבים ורבי שמעון פוטר. הגמרא מפרטת: זה יכול וזה יכול רבי מאיר מחייב ורבי יהודה ורבי שמעון פוטרים, זה אינו יכול וזה אינו יכול רק רבי שמעון פוטר, וזה יכול וזה אינו יכול הכל מחייבים. המחלוקת היא בדרשת 'נפש אחת בעשותה'. החי במטה פטור אפילו לרבנן החולקים על רבי נתן, משום שאדם חי נושא את עצמו, ורבי יוחנן מוסיף שבכפות חייב. רבא מבאר שרבי שמעון פוטר במת משום מלאכה שאינה צריכה לגופה, ומודה במר לחפור ובספר תורה לקרות. ורב ששת ורב נחמן חלוקים בחצי זית שפטור לפי המשנה: לרב ששת כשהוציא חצי זית מכזית ומחצה, לרב נחמן כשהוציא חצי זית ממת גדול.",
    "en": "As written, two who carried out a loaf are exempt, and if one alone could not they are liable, while Rabbi Shimon exempts. The Gemara lays it out: when each could alone, Rabbi Meir holds liable and Rabbi Yehudah and Rabbi Shimon exempt; when neither could, only Rabbi Shimon exempts; and when one could and one could not, all hold liable. The dispute rests on how 'one soul ... in doing it' is expounded. A live person on a bed is exempt even for the Rabbanan who argue with Rabbi Nasan, because a living person carries himself, and Rabbi Yochanan adds that a bound person is different. Rava explains that Rabbi Shimon exempts carrying a corpse because it is a melachah not needed for its own sake, and he agrees about a spade to dig with and a Sefer Torah to read from. And Rav Sheshes and Rav Nachman disagree about the half olive the Mishnah implies is exempt: for Rav Sheshes, he took a half olive from an olive and a half; for Rav Nachman, he took a half olive from a whole corpse."
   },
