   "text": "הַנּוֹטֵל צִפָּרְנָיו זוֹ בָזוֹ, אוֹ בְשִׁנָּיו, וְכֵן שְׂעָרוֹ, וְכֵן שְׂפָמוֹ, וְכֵן זְקָנוֹ, וְכֵן הַגּוֹדֶלֶת, וְכֵן הַכּוֹחֶלֶת, וְכֵן הַפּוֹקֶסֶת, רַבִּי אֱלִיעֶזֶר מְחַיֵּב, וַחֲכָמִים אוֹסְרִין מִשּׁוּם שְׁבוּת. הַתּוֹלֵשׁ מֵעָצִיץ נָקוּב, חַיָּב, וְשֶׁאֵינוֹ נָקוּב, פָּטוּר. וְרַבִּי שִׁמְעוֹן פּוֹטֵר בָּזֶה וּבָזֶה:",
   "gap": {
    "he": "לפי לשון המשנה, בנוטל צפרניו ושערו, בגודלת, בכוחלת ובפוקסת רבי אליעזר מחייב וחכמים אוסרים משום שבות, ובתולש מעציץ נקוב חייב ורבי שמעון פוטר. רבי אלעזר מצמצם: המחלוקת היא רק ביד ולא בכלי, ורק לעצמו ולא לחבירו. בשערו החיוב הוא במלוא פי הזוג, שהם שתי שערות. רבי אבהו מבאר שכוחלת חייבת משום צובעת, וגודלת ופוקסת משום בונה. רבי שמעון משוה נקוב לתלוש לכל דבר, ורק לענין טומאה שאני משום שהתורה ריבתה טהרה אצל זרעים. ובמה מודה רבי שמעון: לרבי זירא כשניקב בכדי טהרתו, ולאביי כשניקב למטה מרביעית.",
    "en": "As written, for removing nails or hair, braiding, applying eye paint and parting hair, Rabbi Eliezer holds liable and the Chachamim forbid as a rabbinic prohibition, and for plucking from a perforated pot one is liable while Rabbi Shimon exempts. Rabbi Elazar narrows it: the dispute is only by hand, not with a tool, and only for oneself, not for another. For hair, liability is for a shear's mouthful, which is two hairs. Rabbi Abahu explains that eye paint is liable as dyeing, and braiding and parting hair as building. Rabbi Shimon treats a perforated pot as detached for everything, except tumah, because the Torah widened purity for seeds. And where Rabbi Shimon agrees: for Rabbi Zeira, when the hole is large enough to make the pot tahor; for Abaye, when the hole is below a revi'is."
   },
