   "id": "11-1",
   "perek": 11,
   "ref": "Mishnah Shabbat 11:1",
   "link": "https://www.sefaria.org/Mishnah_Shabbat.11.1",
   "name": {
    "he": "הזורק מרשות לרשות",
    "en": "Throwing between domains"
   },
   "text": "הַזּוֹרֵק מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים, מֵרְשׁוּת הָרַבִּים לִרְשׁוּת הַיָּחִיד, חַיָּב. מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הַיָּחִיד וּרְשׁוּת הָרַבִּים בָּאֶמְצַע, רַבִּי עֲקִיבָא מְחַיֵּב, וַחֲכָמִים פּוֹטְרִין:",
   "gap": {
    "he": "לפי לשון המשנה, הזורק מרשות היחיד לרשות הרבים או להפך חייב, ובזורק מרשות היחיד לרשות היחיד דרך רשות הרבים רבי עקיבא מחייב וחכמים פוטרים, בלי גבול. הגמרא מסבירה שזריקה היא תולדה של הוצאה, והכנסה שווה להוצאה מסברא, אלא שהוצאה אב והכנסה תולדה. בגבול המחלוקת יש שלש שיטות: רב המנונא מוכיח מברייתא שחולקים למטה מעשרה, והשאלה היא אם קלוטה כמה שהונחה; רבי אלעזר אומר שרבי עקיבא מחייב אפילו למעלה מעשרה; ורב חלקיה בר טובי אומר שבתוך שלשה הכל מחייבים, למעלה מעשרה הכל פוטרים, והמחלוקת היא משלשה ועד עשרה. ברייתא מוסיפה שלמעלה מעשרה האיסור הוא רק משום שבות, ואם שתי הרשויות שלו מותר.",
    "en": "As written, throwing from a private domain to the public domain or the reverse is chayav, and on throwing from one private domain to another across the public domain Rabbi Akiva holds chayav and the Chachamim patur, with no limit given. The Gemara explains that throwing is a toladah of carrying out, and bringing in equals carrying out by reasoning, except that carrying out is the av and bringing in the toladah. On the scope of the dispute there are three views: Rav Hamnuna proves from a baraisa that they disagree below ten tefachim, over whether an object in the air is treated as resting there; Rabbi Elazar says Rabbi Akiva holds chayav even above ten; and Rav Chilkiyah bar Tovi says within three tefachim all hold chayav, above ten all hold patur, and the dispute is from three to ten. A baraisa adds that above ten it is only a rabbinic shevus, and if both domains are his it is permitted."
   },
