   "text": "כֵּיצַד. שְׁתֵּי גְזֻזְטְרָאוֹת זוֹ כְנֶגֶד זוֹ בִרְשׁוּת הָרַבִּים, הַמּוֹשִׁיט וְהַזּוֹרֵק מִזּוֹ לָזוֹ, פָּטוּר. הָיוּ שְׁתֵּיהֶן בִּדְיוֹטָא אַחַת, הַמּוֹשִׁיט חַיָּב, וְהַזּוֹרֵק פָּטוּר, שֶׁכָּךְ הָיְתָה עֲבוֹדַת הַלְוִיִּם, שְׁתֵּי עֲגָלוֹת זוֹ אַחַר זוֹ בִּרְשׁוּת הָרַבִּים, מוֹשִׁיטִין הַקְּרָשִׁים מִזּוֹ לָזוֹ, אֲבָל לֹא זוֹרְקִין. חֻלְיַת הַבּוֹר וְהַסֶּלַע שֶׁהֵן גְּבוֹהִין עֲשָׂרָה וְרָחְבָּן אַרְבָּעָה, הַנּוֹטֵל מֵהֶן וְהַנּוֹתֵן עַל גַּבָּן, חַיָּב, פָּחוֹת מִכֵּן, פָּטוּר:",
   "gap": {
    "he": "לפי לשון המשנה, הלוים הושיטו קרשים בין שתי עגלות ברשות הרבים, והנוטל מחוליית הבור והסלע הגבוהים עשרה ורחבים ארבעה חייב. רב בשם רבי חייא אומר שתחת העגלות, ביניהן ובצדיהן היה רשות הרבים, ואביי מוסיף שבין עגלה לעגלה היה כמלוא אורך עגלה. מכך שהמשנה אומרת חוליית הבור ולא הבור לבד, הגמרא לומדת כרבי יוחנן שהבור וחולייתו מצטרפים לעשרה. בזורק ונח על גבי עמוד, רבא, רב יוסף ואביי אומרים שהמשנה עצמה מחייבת בנוטל ונותן על גבן, ורב מרדכי אומר שאולי המשנה עוסקת במחט שאינה עולה למעלה מן העמוד.",
    "en": "As written, the Levi'im passed boards between two wagons in the public domain, and one who takes from or places on a well's rim or a rock ten tefachim high and four wide is chayav. Rav in the name of Rabbi Chiya says beneath the wagons, between them and beside them was public domain, and Abaye adds that the gap between wagons was a full wagon's length. Since the Mishnah says the rim of the well and not simply the well, the Gemara learns like Rabbi Yochanan that the pit and its rim combine to make ten. On throwing onto a pillar, Rava, Rav Yosef and Abaye say the Mishnah itself makes him chayav when he takes or places on top, while Rav Mordechai says the Mishnah may speak of a needle, which does not rise above the pillar."
   },
