   "text": "הַזּוֹרֵק מִן הַיָּם לַיַּבָּשָׁה וּמִן הַיַּבָּשָׁה לַיָּם, וּמִן הַיָּם לַסְּפִינָה וּמִן הַסְּפִינָה לַיָּם, וּמִן הַסְּפִינָה לַחֲבֶרְתָּהּ, פָּטוּר. סְפִינוֹת קְשׁוּרוֹת זוֹ בָזוֹ, מְטַלְטְלִין מִזּוֹ לָזוֹ. אִם אֵינָן קְשׁוּרוֹת, אַף עַל פִּי שֶׁמֻּקָּפוֹת, אֵין מְטַלְטְלִין מִזּוֹ לָזוֹ:",
   "gap": {
    "he": "לפי לשון המשנה, ספינות קשורות זו בזו מטלטלין מזו לזו, ונראה שזה דבר פשוט. רבא אומר שהחידוש הוא להתיר את הספינה הקטנה שביניהן, ורב ספרא דוחה מלשון המשנה 'מטלטלין מזו לזו' ואומר שהחידוש הוא שצריך לערב ואז מטלטלין. שמואל מוסיף שאפילו קשורות בחוט דק מספיק, והגמרא מעמידה שהספינה יכולה להחזיק את חברתה בו, ולענין שבת זה רק היכר.",
    "en": "As written, ships tied to one another may have objects carried between them, which seems obvious. Rava says the point is to permit the small boat between them, and Rav Safra rejects this from the Mishnah's words \"carry from one to the other\" and says the point is that they must make an eruv and may then carry. Shmuel adds that even tying with a thin thread suffices, and the Gemara sets it where the thread can hold the ships together, since for Shabbos it is only a marker."
   },
