   "name": {
    "he": "הבונה כל שהוא",
    "en": "Building any amount"
   },
   "text": "הַבּוֹנֶה, כַּמָּה יִבְנֶה וִיהֵא חַיָּב, הַבּוֹנֶה כָּל שֶׁהוּא, וְהַמְסַתֵּת, וְהַמַּכֶּה בַפַּטִּישׁ וּבְמַעֲצָד, הַקּוֹדֵחַ כָּל שֶׁהוּא, חַיָּב. זֶה הַכְּלָל, כָּל הָעוֹשֶׂה מְלָאכָה וּמְלַאכְתּוֹ מִתְקַיֶּמֶת בְּשַׁבָּת, חַיָּב. רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר, אַף הַמַּכֶּה בְקֻרְנָס עַל הַסַּדָּן בִּשְׁעַת מְלָאכָה, חַיָּב, מִפְּנֵי שֶׁהוּא כִמְתַקֵּן מְלָאכָה:",
   "gap": {
    "he": "לפי לשון המשנה, הבונה, המסתת, המכה בפטיש והקודח כל שהוא חייבים, בלי טעם. לשאלה למה בנין כל שהוא חשוב, רבי ירמיה אומר שעני חופר גומא להצניע פרוטותיו, אביי אומר שעני עושה כירה קטנה, ורב אחא בר יעקב אומר שבעל הבית סותם נקב בבירתו. במסתת רב אומר שחייב משום בונה ושמואל אומר משום מכה בפטיש, ורבי יוחנן קורא את המשנה 'המסתת המכה בפטיש' בלי וי״ו. בקודח, לשמואל המשנה עוסקת כשהשאיר את המקדח בתוך החור, שזו גמר מלאכה. 'זה הכלל' בא להוסיף את הדוחק קפיזא בקבא. ורבן שמעון בן גמליאל מחייב במכה בקורנס על הסדן משום שכך עשו מרדדי טסי המשכן.",
    "en": "As written, building, chiseling, striking with a hammer and drilling any amount are chayav, with no reason given. On why building any amount matters, Rabbi Yirmiyah says a poor man digs a hole to hide his coins, Abaye says a poor man builds a small stove, and Rav Acha bar Yaakov says a householder plugs a hole in his mansion. For chiseling, Rav says the liability is for building and Shmuel says for striking with a hammer, and Rabbi Yochanan reads the Mishnah as \"chiseling, which is striking with a hammer\" without the \"and\". On drilling, for Shmuel the Mishnah speaks where he left the iron drill in the hole, which completes the work. \"This is the rule\" comes to add pressing a small measure into a larger one. And Rabban Shimon ben Gamliel holds one striking the anvil with a sledge chayav because those who beat out the Mishkan's plates did so."
   },
