   "text": "הַחוֹרֵשׁ כָּל שֶׁהוּא, הַמְנַכֵּשׁ וְהַמְקַרְסֵם וְהַמְזָרֵד כָּל שֶׁהוּא, חַיָּב. הַמְלַקֵּט עֵצִים, אִם לְתַקֵּן, כָּל שֶׁהֵן, אִם לְהֶסֵּק, כְּדֵי לְבַשֵּׁל בֵּיצָה קַלָּה. הַמְלַקֵּט עֲשָׂבִים, אִם לְתַקֵּן, כָּל שֶׁהוּא, אִם לִבְהֵמָה, כִּמְלֹא פִי הַגְּדִי:",
   "gap": {
    "he": "לפי לשון המשנה, החורש כל שהוא חייב, ולא מפורש מה התועלת בחרישה כה קטנה. הגמרא מסבירה שהיא ראויה לזרוע בה גרעין של דלעת, וכנגדה במשכן ראויה לשתול קלח אחד של סממנים.",
    "en": "As written, plowing any amount is chayav, without saying what use so small a furrow has. The Gemara explains that it is fit for planting a gourd seed, and its parallel in the Mishkan is that it is fit for planting one stalk of the dye plants."
   },
