   "text": "יָשַׁב הָאֶחָד עַל הַפֶּתַח וְלֹא מִלְּאָהוּ, יָשַׁב הַשֵּׁנִי וּמִלְּאָהוּ, הַשֵּׁנִי חַיָּב. יָשַׁב הָרִאשׁוֹן עַל הַפֶּתַח וּמִלְּאָהוּ, וּבָא הַשֵּׁנִי וְיָשַׁב בְּצִדּוֹ, אַף עַל פִּי שֶׁעָמַד הָרִאשׁוֹן וְהָלַךְ לוֹ, הָרִאשׁוֹן חַיָּב וְהַשֵּׁנִי פָּטוּר. הָא לְמַה זֶּה דוֹמֶה, לְנוֹעֵל אֶת בֵּיתוֹ לְשָׁמְרוֹ וְנִמְצָא צְבִי שָׁמוּר בְּתוֹכוֹ:",
