     "q": "אֵין עוֹשִׂין מֵי מֶלַח מְרוּבִּין לָתֵת לְתוֹךְ הַכְּבָשִׁין שֶׁבְּתוֹךְ גִּיסְטְרָא... אָמַר רַבִּי יוֹסֵי: וְכִי מִפְּנֵי שֶׁהַלָּלוּ מְרוּבִּין וְהַלָּלוּ מוּעָטִין הַלָּלוּ אֲסוּרִין וְהַלָּלוּ מוּתָּרִין?... אֶלָּא אֵלּוּ וָאֵלּוּ אֲסוּרִין הֵן. וְאֵלּוּ הֵן מֵי מֶלַח הַמּוּתָּרִין — נוֹתֵן שֶׁמֶן וּמֶלַח אוֹ שֶׁמֶן וּמַיִם, וּבִלְבַד שֶׁלֹּא יִתֵּן מַיִם וּמֶלַח לְכַתְּחִלָּה.",
