   "text": "אֵין אוֹכְלִין אֵזוֹב יוֹן בְּשַׁבָּת, לְפִי שֶׁאֵינוֹ מַאֲכַל בְּרִיאִים, אֲבָל אוֹכֵל הוּא אֶת יוֹעֶזֶר וְשׁוֹתֶה אַבּוּב רוֹעֶה. כָּל הָאֳכָלִין אוֹכֵל אָדָם לִרְפוּאָה, וְכָל הַמַּשְׁקִין שׁוֹתֶה, חוּץ מִמֵּי דְקָלִים וְכוֹס עִקָּרִים, מִפְּנֵי שֶׁהֵן לַיְרוֹקָה. אֲבָל שׁוֹתֶה הוּא מֵי דְקָלִים לִצְמָאוֹ, וְסָךְ שֶׁמֶן עִקָּרִין שֶׁלֹּא לִרְפוּאָה:",
   "gap": {
    "he": "לפי לשון המשנה, אין אוכלים אזוביון בשבת, אבל אוכלים יועזר ושותים אבוברואה, וכל האוכלים והמשקים מותרים לרפואה חוץ ממי דקלים וכוס עיקרין. רב יוסף מבאר שאזוביון הוא 'אברתה בר הינג', שונה מאזוב. יועזר הוא פותנק, שאוכלים אותו לתולעים. 'כל האוכלין' בא לרבות טחול לשיניים וכרשינין לבני מעיים, ו'כל המשקין' בא לרבות מי צלפים בחומץ. רבא מדייק ש'כל המשקין' הם משקים שבני אדם שותים, ולכן לא מי רגלים. מי דקלים, או מי דקרים, הם מעיין שיוצא בין שני דקלים, והכוסות ממנו מרפים ומשלשלים. וכוס עיקרין הוא תערובת שרבי יוחנן מפרט, לזבה ביין ולירקון בשכר.",
    "en": "As written, one may not eat ezov yavan on Shabbos, but may eat yo'ezer and drink abuvro'eh, and all foods and drinks may be taken as medicine except palm water and the cup of roots. Rav Yosef explains that ezov yavan is \"avrasa bar hing,\" distinct from ezov. Yo'ezer is putnak, eaten against worms. \"All foods\" comes to include spleen for the teeth and vetch for the intestines, and \"all drinks\" comes to include caper water in vinegar. Rava infers that \"all drinks\" means drinks people drink, so not urine. Palm water, or \"piercing water,\" is a spring that flows between two palms, and its cups loosen and purge. And the cup of roots is a mixture Rabbi Yochanan details, in wine for a zavah and in beer for jaundice."
   },
