   "text": "יֵשׁ לְךָ קְשָׁרִים שֶׁאֵין חַיָּבִין עֲלֵיהֶן כְּקֶשֶׁר הַגַּמָּלִין וּכְקֶשֶׁר הַסַּפָּנִין. קוֹשֶׁרֶת אִשָּׁה מִפְתַּח חֲלוּקָהּ, וְחוּטֵי סְבָכָה וְשֶׁל פְּסִיקְיָא, וּרְצוּעוֹת מִנְעָל וְסַנְדָּל, וְנוֹדוֹת יַיִן וָשֶׁמֶן, וּקְדֵרָה שֶׁל בָּשָׂר. רַבִּי אֱלִיעֶזֶר בֶּן יַעֲקֹב אוֹמֵר, קוֹשְׁרִין לִפְנֵי הַבְּהֵמָה בִּשְׁבִיל שֶׁלֹּא תֵצֵא. קוֹשְׁרִין דְּלִי בִּפְסִיקְיָא, אֲבָל לֹא בְחֶבֶל. רַבִּי יְהוּדָה מַתִּיר. כְּלָל אָמַר רַבִּי יְהוּדָה, כָּל קֶשֶׁר שֶׁאֵינוֹ שֶׁל קְיָמָא, אֵין חַיָּבִין עָלָיו:",
   "gap": {
    "he": "לפי לשון המשנה, יש קשרים שאין חייבים עליהם, משמע פטור אבל אסור, ובכל זאת אשה קושרת לכתחילה מפתח חלוקה, חוטי סבכה, רצועות מנעל, נודות וקדרה. הגמרא קוראת שני חלקים: קשר שקושרים בזמם ובאיסטרידא פטור אבל אסור, ויש מותרים לכתחילה כמפתח חלוקה. מפתח חלוקה נצרך כשיש לו שני פתחים, וחוטי סבכה כשהיא רחבה, שאשה חסה על שערה ומתירה. נודות שיש להם שני פיות, קדרה שיש לה שלאכא, ולפני הבהמה שיש שני איסרים, כולם מותרים אף שאפשר שיבטל אחד מהם. החבל שאוסרים בדלי הוא חבל של גרדי, ונחלקו אם גוזרים אותו אטו חבל רגיל, ולחכמים הגזירה משום שחבל בחבל מתחלף. ושמואל פוסק כרבי אליעזר בן יעקב.",
    "en": "As written, there are knots one is not liable for, implying exempt but forbidden, and yet a woman ties her garment opening, hairnet strings, shoe straps, flasks and a meat pot from the outset. The Gemara reads two parts: the knot tying on the nose ring or the ship's rope is exempt but forbidden, and some are permitted from the outset, such as the garment opening. The garment opening is needed where it has two openings, and the hairnet strings where it is loose, since a woman spares her hair and unties it. Flasks with two spouts, a pot with a ladle cord, and tying before an animal with two ropes are all permitted even though one of them might be left in place. The rope forbidden for the bucket is a weaver's rope, and the dispute is whether it is decreed against because of an ordinary rope, and for the Chachamim the decree is because one rope is confused with another. And Shmuel rules like Rabbi Eliezer ben Yaakov."
   },
