   "text": "מְקַפְּלִין אֶת הַכֵּלִים אֲפִלּוּ אַרְבָּעָה וַחֲמִשָּׁה פְעָמִים, וּמַצִּיעִין אֶת הַמִּטּוֹת מִלֵּילֵי שַׁבָּת לְשַׁבָּת, אֲבָל לֹא מִשַּׁבָּת לְמוֹצָאֵי שַׁבָּת. רַבִּי יִשְׁמָעֵאל אוֹמֵר, מְקַפְּלִין אֶת הַכֵּלִים וּמַצִּיעִין אֶת הַמִּטּוֹת מִיּוֹם הַכִּפּוּרִים לְשַׁבָּת, וְחֶלְבֵי שַׁבָּת קְרֵבִין בְּיוֹם הַכִּפּוּרִים. (אֲבָל לֹא שֶׁל יוֹם הַכִּפּוּרִים בְּשַׁבָּת). רַבִּי עֲקִיבָא אוֹמֵר לֹא שֶׁל שַׁבָּת קְרֵבִין בְּיוֹם הַכִּפּוּרִים, וְלֹא שֶׁל יוֹם הַכִּפּוּרִים קְרֵבִין בְּשַׁבָּת:",
   "gap": {
    "he": "לפי לשון המשנה, מקפלים כלים אפילו ארבע וחמש פעמים, ורבי ישמעאל ורבי עקיבא חולקים אם חלבי שבת קרבים ביום הכיפורים. דבי רבי ינאי מצמצמים: רק אדם אחד, בכלים חדשים ולבנים, וכשאין לו להחליף. הברייתא מביאה את מקור המחלוקת מ'עולת שבת בשבתו': לרבי ישמעאל הפסוק מתיר חלבי שבת ביום הכיפורים, ולרבי עקיבא ביום טוב בלבד. ושורש הדבר הוא אם נדרים ונדבות קרבים ביום טוב.",
    "en": "As written, one may fold garments even four or five times, and Rabbi Yishmael and Rabbi Akiva disagree whether the fats of Shabbos are offered on Yom Kippur. The house of Rabbi Yannai narrows it: only by one person, with new and white garments, and when he has nothing to change into. A baraisa gives the source of the dispute in \"the olah of Shabbos on its Shabbos\": for Rabbi Yishmael the pasuk permits the fats of Shabbos on Yom Kippur, and for Rabbi Akiva only on Yom Tov. And the root is whether vow and gift offerings are brought on Yom Tov."
   },
