    "en": "As written, one may overturn a bowl over a child's excrement. Rav Chanan bar Rava explains that excrement itself is ready for dogs, so one should read \"over chickens' excrement, because of a child.\" And the Gemara sets it in a refuse heap within the courtyard, so it is not a chamber pot that may simply be taken out."
