   "name": {
    "he": "קנה של זיתים",
    "en": "The olive reed"
   },
   "text": "קָנֶה שֶׁל זֵיתִים, אִם יֵשׁ קֶשֶׁר בְּרֹאשׁוֹ, מְקַבֵּל טֻמְאָה, וְאִם לָאו, אֵין מְקַבֵּל טֻמְאָה. בֵּין כָּךְ וּבֵין כָּךְ, נִטָּל בְּשַׁבָּת:",
   "gap": {
    "he": "לפי לשון המשנה, קנה של זיתים שיש קשר בראשו מקבל טומאה, ואינה מסבירה למה, שהרי פשוטי כלי עץ אינם מקבלים טומאה. הגמרא מביאה ברייתא בשם רבי נחמיה: בשעה שמהפך בזיתים הופכו ורואה בו, כלומר הקשר משמש כבית קיבול.",
    "en": "As written, an olive reed with a knot at its top is susceptible to tumah, without saying why, since flat wooden implements are not susceptible. The Gemara brings a teaching in the name of Rabbi Nechemyah: when he turns the olives he turns the reed over and looks into it, so the knot serves as a receptacle."
   },
