   "text": "הָאֶבֶן שֶׁבְּקֵרוּיָה, אִם מְמַלְּאִין בָּהּ וְאֵינָהּ נוֹפֶלֶת, מְמַלְּאִין בָּהּ. וְאִם לָאו, אֵין מְמַלְּאִין בָּהּ. זְמוֹרָה שֶׁהִיא קְשׁוּרָה בְטָפִיחַ, מְמַלְּאִין בָּהּ בְּשַׁבָּת:",
   "gap": {
    "he": "לפי לשון המשנה, אבן שבקרויה שאינה נופלת ממלאים בה, ואם לאו אין ממלאים בה, וזמורה קשורה בטפיח ממלאים בה. רבה מסביר שכשהידק את האבן עשאה דופן לקרויה. רב יוסף מסביר שכשלא הידקה, ביטלה. מן 'קשורה' משמע שאינה קשורה אסורה, ולכאורה דלא כרבן שמעון בן גמליאל; רב שישת מעמיד בזמורה המחוברת באביה, ורב אשי אומר שאפילו בתלושה גזרו שמא יקטום.",
    "en": "As written, a stone in a gourd that does not fall out may be used to draw water, otherwise not, and a vine branch tied to a pitcher may be used. Rabbah explains that once he fastened the stone he made it a wall of the gourd. Rav Yosef explains that when he did not fasten it, he annulled it. From \"tied\" it follows that an untied branch is forbidden, seemingly not like Rabban Shimon ben Gamliel; Rav Sheshes sets it in a branch still attached to its vine, and Rav Ashi says even a detached one was forbidden lest he trim it."
   },
