   "text": "פְּקַק הַחַלּוֹן, רַבִּי אֱלִיעֶזֶר אוֹמֵר, בִּזְמַן שֶׁהוּא קָשׁוּר וְתָלוּי, פּוֹקְקִין בּוֹ, וְאִם לָאו, אֵין פּוֹקְקִין בּוֹ. וַחֲכָמִים אוֹמְרִים, בֵּין כָּךְ וּבֵין כָּךְ פּוֹקְקִין בּוֹ:",
