    "en": "As written, Rabbi Eliezer and the Chachamim disagree whether one may plug a window with a plug that is not tied and hanging. Rabbi Yochanan narrows it: all agree one may not make a temporary tent from the start, and they disagree only about adding to one. What the Chachamim's \"either way\" means is disputed: for Rav Kahana, whether tied or not, provided it is prepared for the purpose; for Rabbi Yirmiyah, whether hanging or not, provided it is tied."
