   "text": "מְפַנִּין אֲפִלּוּ אַרְבַּע וְחָמֵשׁ קֻפּוֹת שֶׁל תֶּבֶן וְשֶׁל תְּבוּאָה מִפְּנֵי הָאוֹרְחִים וּמִפְּנֵי בִטּוּל בֵּית הַמִּדְרָשׁ, אֲבָל לֹא אֶת הָאוֹצָר. מְפַנִּין תְּרוּמָה טְהוֹרָה, וּדְמַאי, וּמַעֲשֵׂר רִאשׁוֹן שֶׁנִּטְּלָה תְרוּמָתוֹ, וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁנִּפְדּוּ, וְהַתֻּרְמוֹס הַיָּבֵשׁ, מִפְּנֵי שֶׁהוּא מַאֲכָל לַעֲנִיִּים. אֲבָל לֹא אֶת הַטֶּבֶל, וְלֹא מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְרוּמָתוֹ, וְלֹא אֶת מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ, וְלֹא אֶת הַלּוּף, וְלֹא הַחַרְדָּל. רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל מַתִּיר בְּלוּף, מִפְּנֵי שֶׁהוּא מַאֲכַל עוֹרְבִין:",
   "gap": {
    "he": "לפי לשון המשנה, מפנים ארבע וחמש קופות אבל לא את האוצר, ומפנים פירות מסוימים ולא אחרים. רב חסדא קורא ארבע מתוך חמש וחמש מאוצר גדול, ואבל לא את האוצר הוא שלא יתחיל באוצר, כרבי יהודה שיש לו מוקצה; שמואל קורא ארבע וחמש כדרך דיבור, ואבל לא את האוצר הוא שלא יגמור כולו שמא ישווה גומות, כרבי שמעון. תרומה טהורה נצרכה כשהיא ביד ישראל, כיון שראויה לכהן. דמאי מותר כיון שאם ירצה יפקיר נכסיו ויהיה עני. מעשר ראשון שניטלה תרומתו נצרך כשהקדימו בשבלים ולא ניטלה ממנו תרומה גדולה. מעשר שני שנפדה מותר אף שלא נתן את החומש. הטבל האסור הוא אף טבל מדרבנן, ושלא נפדו כולל שנפדו שלא כהלכתן. ותורמוס דווקא יבש, כי לח מר ואין העז אוכלתו.",
    "en": "As written, one may clear away four or five baskets but not the storehouse, and certain produce but not other produce. Rav Chisda reads four out of five and five from a large storehouse, and \"not the storehouse\" means not to begin it, following Rabbi Yehudah who holds of muktzeh; Shmuel reads \"four or five\" as a figure of speech, and \"not the storehouse\" means not to finish it lest he level the floor, following Rabbi Shimon. Pure terumah was needed for when it is in a Yisrael's hands, since it is fit for a Kohen. Demai is permitted since he could renounce his property and become poor. First tithe whose terumah was taken was needed where he took it early at the stalk stage and terumah gedolah was not taken. Redeemed second tithe is permitted even if the added fifth was not paid. The forbidden tevel includes tevel by rabbinic law, and \"not redeemed\" includes redemption not done properly. And lupine only when dry, since fresh it is bitter and the goat will not eat it."
   },
