   "text": "אֵין מְיַלְּדִין אֶת הַבְּהֵמָה בְיוֹם טוֹב, אֲבָל מְסַעֲדִין. וּמְיַלְּדִין אֶת הָאִשָּׁה בְּשַׁבָּת, וְקוֹרִין לָהּ חֲכָמָה מִמָּקוֹם לְמָקוֹם, וּמְחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת, וְקוֹשְׁרִין אֶת הַטַּבּוּר. רַבִּי יוֹסֵי אוֹמֵר, אַף חוֹתְכִין. וְכָל צָרְכֵי מִילָה עוֹשִׂין בְּשַׁבָּת:",
   "gap": {
    "he": "לפי לשון המשנה, אין מילדים בהמה ביום טוב אבל מסעדים, ומחללים שבת על היולדת, ורבי יוסי מתיר אף לחתוך את הטבור. במה מסעדים נחלקו: לרב יהודה אוחז את הולד שלא יפול, ולרב נחמן דוחק בבשר כדי שיצא, וברייתא כרב יהודה. 'ומחללין עליה את השבת' בא לרבות שחברתה מדליקה לה נר ומביאה לה שמן. עד מתי היא יולדת: לשמואל כפי רב אשי, אחר שנסתם הקבר אין מחללים אף אם אמרה צריכה אני, וכפי מר זוטרא מחללים אם אמרה צריכה אני, והלכה כמר זוטרא. חכמים מודים לרבי יוסי בטבור של שני תינוקות שחותכים, כי מושכים זה את זה. ורב פוסק כרבי יוסי.",
    "en": "As written, one may not deliver an animal on Yom Tov but may assist, Shabbos is desecrated for a woman giving birth, and Rabbi Yosi permits even cutting the umbilical cord. How one assists is disputed: for Rav Yehudah, one holds the newborn so it does not fall, and for Rav Nachman, one presses the flesh so it comes out, and a baraisa follows Rav Yehudah. \"And Shabbos is desecrated for her\" comes to include that her friend lights a lamp for her and brings her oil. How long she counts as a yoledes: Shmuel as taught by Rav Ashi says that once the womb has closed one does not desecrate Shabbos even if she says she needs it, and as taught by Mar Zutra one does if she says she needs it, and the halacha follows Mar Zutra. The Chachamim agree with Rabbi Yosi that the cord of twins is cut, since they pull on each other. And Rav rules like Rabbi Yosi."
   },
