   "id": "19-3",
   "perek": 19,
   "ref": "Mishnah Shabbat 19:3",
   "link": "https://www.sefaria.org/Mishnah_Shabbat.19.3",
   "name": {
    "he": "רחיצת התינוק, ספק ואנדרוגינוס",
    "en": "Washing the baby; doubtful and androgynous"
   },
   "text": "מַרְחִיצִין אֶת הַקָּטָן, בֵּין לִפְנֵי הַמִּילָה וּבֵין לְאַחַר הַמִּילָה, וּמְזַלְּפִין עָלָיו בַּיָּד, אֲבָל לֹא בִכְלִי. רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר, מַרְחִיצִין אֶת הַקָּטָן בַּיּוֹם הַשְּׁלִישִׁי שֶׁחָל לִהְיוֹת בְּשַׁבָּת, שֶׁנֶּאֱמַר (בראשית לד) וַיְהִי בַיּוֹם הַשְּׁלִישִׁי בִּהְיוֹתָם כֹּאֲבִים. סָפֵק וְאַנְדְּרוֹגִינוֹס אֵין מְחַלְּלִין עָלָיו אֶת הַשַּׁבָּת, וְרַבִּי יְהוּדָה מַתִּיר בְּאַנְדְּרוֹגִינוֹס:",
   "gap": {
    "he": "לפי לשון המשנה, מרחיצים את התינוק לפני המילה ואחריה, ומזלפים ביד ולא בכלי, ורבי אלעזר בן עזריה מתיר לרחוץ ביום השלישי שחל בשבת. רב יהודה ורבה בר אבוה גורסים 'כיצד': הרחיצה עצמה היא זילוף ביד, ורבא קורא שביום הראשון רוחצים כדרכו וביום השלישי בשבת מזלפים. אך רבא עצמו מודה שהמשנה מדויקת כמותם: אם תנא קמא אומר מזלפים, מובן שרבי אלעזר בן עזריה אומר מרחיצים. ברייתא לומדת מ'ערלתו' שרק ודאי דוחה שבת, ולא ספק ולא אנדרוגינוס. רב חסדא מצמצם את רבי יהודה: לא לכל דבר אמר שאנדרוגינוס זכר, והגמרא מבארת שבמילה כתוב 'כל זכר'. והלכה כרבי אלעזר בן עזריה, בין ברחיצת כל הגוף ובין ברחיצת המילה, בין בחמין שהוחמו בשבת ובין מערב שבת, מפני שסכנה היא לו.",
    "en": "As written, the baby is washed before and after the milah, water is sprinkled by hand but not from a vessel, and Rabbi Elazar ben Azaryah allows washing on the third day that falls on Shabbos. Rav Yehudah and Rabbah bar Avuha read \"how so\": the washing itself is sprinkling by hand, while Rava reads that on the first day one washes normally and on the third day that falls on Shabbos one sprinkles. But Rava himself concedes the Mishnah is precise like them: if the first Tanna says sprinkle, it makes sense that Rabbi Elazar ben Azaryah says wash. A baraisa learns from \"his orlah\" that only a certain case overrides Shabbos, not a doubtful one and not an androgynous. Rav Chisda narrows Rabbi Yehudah: he did not call an androgynous male for everything, and the Gemara explains that for milah it says \"every male\". And the halacha follows Rabbi Elazar ben Azaryah, for the whole body and for the milah, with water heated on Shabbos or before Shabbos, because it is a danger for him."
   },
