   "name": {
    "he": "ציצין המעכבין",
    "en": "Shreds that invalidate the milah"
   },
   "text": "אֵלּוּ הֵן צִיצִין הַמְעַכְּבִין אֶת הַמִּילָה, בָּשָׂר הַחוֹפֶה אֶת רֹב הָעֲטָרָה. וְאֵינוֹ אוֹכֵל בַּתְּרוּמָה. וְאִם הָיָה בַעַל בָּשָׂר, מְתַקְּנוֹ מִפְּנֵי מַרְאִית הָעָיִן. מָל וְלֹא פָרַע אֶת הַמִּילָה, כְּאִלּוּ לֹא מָל:",
   "gap": {
    "he": "לפי לשון המשנה, ציצין המעכבים הם בשר החופה את רוב העטרה, ובעל בשר מתקנים אותו מפני מראית העין. רב מבאר ש'רוב העטרה' הוא רוב גובהה. בקטן המסורבל בבשר נחלקו שמואל ורבן שמעון בן גמליאל: לשמואל אינו צריך למול אם נראה מהול בשעת קישוי, ולרבן שמעון בן גמליאל צריך למול רק אם אינו נראה מהול. וההבדל ביניהם הוא במקרה שנראה ואינו נראה.",
    "en": "As written, invalidating shreds are flesh covering most of the corona, and one with excess flesh is corrected because of appearances. Rav explains that \"most of the corona\" means most of its height. On a baby heavy with flesh Shmuel and Rabban Shimon ben Gamliel disagree: for Shmuel he need not be circumcised again if he looks circumcised when erect, and for Rabban Shimon ben Gamliel he must be circumcised only if he does not look circumcised. The difference between them is the case where he partly looks and partly does not."
   },
