   "name": {
    "he": "תליית המשמרת",
    "en": "Hanging the strainer"
   },
   "text": "רַבִּי אֱלִיעֶזֶר אוֹמֵר, תּוֹלִין אֶת הַמְשַׁמֶּרֶת בְּיוֹם טוֹב, וְנוֹתְנִין לַתְּלוּיָה בְשַׁבָּת. וַחֲכָמִים אוֹמְרִים, אֵין תּוֹלִין אֶת הַמְשַׁמֶּרֶת בְּיוֹם טוֹב, וְאֵין נוֹתְנִין לַתְּלוּיָה בְשַׁבָּת, אֲבָל נוֹתְנִין לַתְּלוּיָה בְיוֹם טוֹב:",
   "gap": {
    "he": "לפי לשון המשנה, רבי אליעזר מתיר לתלות משמרת ביום טוב, וחכמים אוסרים לתלות ביום טוב ולתת לתלויה בשבת. הגמרא מבארת שרבי אליעזר סובר כרבי יהודה שמכשירי אוכל נפש מותרים ביום טוב, ומרחיק יותר ממנו. אביי מבאר שאיסור חכמים לתלות הוא מדרבנן, שלא יעשה כדרך שעושה בחול. רב כהנא אומר שהנותן לתלויה בשבת חייב חטאת. ונחלקו משום איזו מלאכה: לרבה משום בורר, ולרבי זירא משום מרקד.",
    "en": "As written, Rabbi Eliezer allows hanging a strainer on Yom Tov, while the Chachamim forbid hanging it on Yom Tov and pouring into a hanging one on Shabbos. The Gemara explains that Rabbi Eliezer holds like Rabbi Yehudah that preparations for food are permitted on Yom Tov, and goes even further than him. Abaye explains that the Chachamim's ban on hanging is rabbinic, so that one not act as on a weekday. Rav Kahana says one who strains on Shabbos is liable to a chatas. And they disagree which melachah it is: for Rabbah selecting, for Rabbi Zeira sifting."
   },
