   "ref": "Mishnah Shabbat 20:2",
   "link": "https://www.sefaria.org/Mishnah_Shabbat.20.2",
   "name": {
    "he": "סינון יין, ביצה ואנומלין",
    "en": "Straining wine, the egg, and anomalin"
   },
   "text": "נוֹתְנִין מַיִם עַל גַּבֵּי הַשְּׁמָרִים בִּשְׁבִיל שֶׁיִּצַּלּוּ, וּמְסַנְּנִין אֶת הַיַּיִן בְּסוּדָרִין וּבִכְפִיפָה מִצְרִית, וְנוֹתְנִין בֵּיצָה בִמְסַנֶּנֶת שֶׁל חַרְדָּל, וְעוֹשִׂין אֵנוּמְלִין בְּשַׁבָּת. רַבִּי יְהוּדָה אוֹמֵר, בְּשַׁבָּת, בְּכוֹס, בְּיוֹם טוֹב, בְּלָגִין, וּבַמּוֹעֵד, בְּחָבִית. רַבִּי צָדוֹק אוֹמֵר, הַכֹּל לְפִי הָאוֹרְחִין:",
   "gap": {
    "he": "לפי לשון המשנה, מסננים יין בסודרים ובכפיפה מצרית, נותנים ביצה במסננת של חרדל ועושים אנומלין בשבת. זעירי מגביל שנותנים למשמרת בשבת רק יין ומים צלולים, ולא עכורים. רב שימי בר חייא מגביל את הסינון בסודר שלא יעשה גומא, ורב מגביל את הכפיפה שלא יגביה טפח מקרקעית הכלי. יעקב קרחה מבאר שמותר לתת ביצה במסננת כי עושים זאת רק לצבע. וברייתא מגדירה אנומלין: יין, דבש ופלפלין.",
    "en": "As written, wine is strained through cloths and an Egyptian basket, an egg is put in a mustard strainer, and anomalin is made on Shabbos. Ze'iri limits pouring into a strainer on Shabbos to clear wine and clear water, not cloudy. Rav Shimi bar Chiya limits straining through a cloth to where one does not make a hollow, and Rav limits the basket to where one does not raise it a tefach from the bottom of the vessel. Yaakov Karchah explains that the egg may go in the strainer because it is done only for color. And a baraisa defines anomalin: wine, honey and pepper."
   },
