   "text": "הַקַּשׁ שֶׁעַל גַּבֵּי הַמִּטָּה, לֹא יְנַעְנְעוֹ בְיָדוֹ, אֶלָּא מְנַעְנְעוֹ בְגוּפוֹ. וְאִם הָיָה מַאֲכַל בְּהֵמָה, אוֹ שֶׁהָיָה עָלָיו כַּר אוֹ סָדִין, מְנַעְנְעוֹ בְיָדוֹ. מַכְבֵּשׁ שֶׁל בַּעֲלֵי בָתִּים, מַתִּירִין, אֲבָל לֹא כוֹבְשִׁין. וְשֶׁל כּוֹבְסִין, לֹא יִגַּע בּוֹ. רַבִּי יְהוּדָה אוֹמֵר, אִם הָיָה מֻתָּר מֵעֶרֶב שַׁבָּת, מַתִּיר אֶת כֻּלּוֹ וְשׁוֹמְטוֹ:",
