    "he": "לפי לשון המשנה, את הקש שעל המטה מנענעים בגוף ולא ביד, אלא אם הוא מאכל בהמה או שיש עליו כר או סדין. ומכבש של בעלי בתים מתירים ואין כובשים. בי רב מדייקים מן הרישא שטלטול מן הצד, כמו בגופו, אינו נחשב טלטול, דלא כרב נחמן.",
