   "text": "הָאֶבֶן שֶׁעַל פִּי הֶחָבִית, מַטָּהּ עַל צִדָּהּ וְהִיא נוֹפֶלֶת. הָיְתָה בֵין הֶחָבִיּוֹת, מַגְבִּיהַּ וּמַטָּהּ עַל צִדָּהּ וְהִיא נוֹפֶלֶת. מָעוֹת שֶׁעַל הַכַּר, נוֹעֵר אֶת הַכַּר וְהֵן נוֹפְלוֹת. הָיְתָה עָלָיו לַשְׁלֶשֶׁת, מְקַנְּחָהּ בִּסְמַרְטוּט. הָיְתָה שֶׁל עוֹר, נוֹתְנִין עָלֶיהָ מַיִם עַד שֶׁתִּכְלֶה:",
   "gap": {
    "he": "לפי לשון המשנה, אבן שעל פי החבית מטה אותה והיא נופלת, ומעות שעל הכר מנער את הכר. רב מעמיד בשוכח, אבל המניח בכוונה עשה את החבית בסיס לדבר האסור. מה שצריך להטות ולא ליטול את האבן הוא כרבן שמעון בן גמליאל, שהאבן כפסולת מרובה על האוכל, ובהיתר טורחים ולא באיסור. ורבי יוחנן מוסיף שניעור הכר הוא רק לצורך גופו, אבל לצורך מקומו מטלטלו כשהמעות עליו.",
    "en": "As written, a stone on the mouth of a barrel is tilted off, and coins on a pillow are shaken off. Rav sets this where he forgot it there, but if he placed it deliberately the barrel became a base for something forbidden. That one must tilt rather than lift the stone follows Rabban Shimon ben Gamliel: the stone is like refuse that outweighs the food, and one takes trouble with the permitted, not with the forbidden. And Rabbi Yochanan adds that shaking the pillow is only when it is needed for its own use, but when its place is needed he may move it with the coins still on it."
   },
