   "gap": {
    "he": "לפי לשון המשנה, בית שמאי ובית הלל חולקים איך מסלקים עצמות וקליפין מן השולחן, מעבירים פירורין ושער אפונין, וספוג בלי בית אחיזה אין מקנחים בו. רב נחמן מעמיד את המחלוקת במוקצה: בית שמאי כרבי יהודה ובית הלל כרבי שמעון. מ'מעבירין' פירורין מסייעים לרבי יוחנן שאסור לאבד פירורין בידיים. שער של אפונין מותר משום שהמשנה כרבי שמעון שאין לו מוקצה. ואיסור הספוג אינו כרבי יהודה, שאף רבי שמעון מודה בפסיק רישיה.",
    "en": "As written, Beis Shammai and Beis Hillel disagree how bones and shells are cleared from the table, crumbs and pea pods may be removed, and a sponge without a handle may not be used for wiping. Rav Nachman places the dispute in muktzeh: Beis Shammai follow Rabbi Yehuda and Beis Hillel follow Rabbi Shimon. From \"one removes\" crumbs the Gemara supports Rabbi Yochanan, that destroying crumbs by hand is forbidden. Pea pods are allowed because the Mishnah follows Rabbi Shimon, who has no muktzeh. And the sponge prohibition does not follow Rabbi Yehuda, since even Rabbi Shimon agrees where the result is inevitable (psik reisha)."
   },
