   "name": {
    "he": "שובר אדם את החבית",
    "en": "Breaking a barrel for dried figs"
   },
   "text": "שׁוֹבֵר אָדָם אֶת הֶחָבִית לֶאֱכֹל הֵימֶנָּה גְרוֹגָרוֹת, וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לַעֲשׂוֹת כְּלִי. וְאֵין נוֹקְבִים מְגוּפָה שֶׁל חָבִית, דִּבְרֵי רַבִּי יְהוּדָה. וַחֲכָמִים מַתִּירִין. וְלֹא יִקְּבֶנָּה מִצִּדָּהּ. וְאִם הָיְתָה נְקוּבָה, לֹא יִתֵּן עָלֶיהָ שַׁעֲוָה, מִפְּנֵי שֶׁהוּא מְמָרֵחַ. אָמַר רַבִּי יְהוּדָה, מַעֲשֶׂה בָא לִפְנֵי רַבָּן יוֹחָנָן בֶּן זַכַּאי בַּעֲרָב, וְאָמַר, חוֹשְׁשָׁנִי לוֹ מֵחַטָּאת:",
   "gap": {
    "he": "לפי לשון המשנה, שובר אדם חבית לאכול ממנה גרוגרות, ונחלקו רבי יהודה וחכמים בנקיבת המגופה, ולא יקבנה מצדה. רבי אושעיא מעמיד בגרוגרות דרוסות, ואומר שהמשנה כרבי נחמיה ולא כרבנן. רבא מדייק זאת מכך שהמשנה נקטה 'גרוגרות' ולא 'פירות'. ובגבול המחלוקת: לרב הונא נחלקו בנקיבה מלמעלה, אבל מן הצד הכל אוסרים וזהו 'לא יקבנה מצדה', ולרב חסדא נחלקו מן הצד, אבל מלמעלה הכל מתירים, ו'לא יקבנה מצדה' הוא בגוף החבית.",
    "en": "As written, one may break a barrel to eat dried figs from it, Rabbi Yehuda and the Chachamim disagree about piercing the stopper, and one may not pierce it from the side. Rabbi Oshaya sets it in pressed figs and says the Mishnah follows Rabbi Nechemyah, not the Rabbanan. Rava infers this from the Mishnah saying \"dried figs\" rather than \"fruit.\" On the scope of the dispute: for Rav Huna they disagree about piercing from above, while from the side all forbid, which is \"not from the side\"; for Rav Chisda they disagree about the side, while from above all permit, and \"not from the side\" refers to the body of the barrel."
   },
