   "text": "הָרוֹחֵץ בְּמֵי מְעָרָה וּבְמֵי טְבֶרְיָא וְנִסְתַּפֵּג, אֲפִלּוּ בְעֶשֶׂר אֲלוּנְטִיאוֹת, לֹא יְבִיאֵם בְּיָדוֹ. אֲבָל עֲשָׂרָה בְנֵי אָדָם מִסְתַּפְּגִין בַּאֲלוּנְטִית אַחַת פְּנֵיהֶם יְדֵיהֶם וְרַגְלֵיהֶם, וּמְבִיאִין אוֹתָהּ בְּיָדָן:",
   "gap": {
    "he": "לפי לשון המשנה, הרוחץ במי מערה ובמי טבריה לא יביא בידו את האלונטיאות, אבל עשרה בני אדם מביאים אלונטית אחת. מי מערה הם חמים כמי טבריה. מלשון 'הרוחץ' משמע שרחיצה רק בדיעבד, ומכלל זה שהשתטפות מותרת לכתחילה, וזו שיטת רבי שמעון. הרישא והסיפא מלמדות חידוש: אדם אחד אפילו בעשר אלונטיות בא לידי סחיטה, ורבים מזכירים זה את זה. ולרבי יוחנן שפוסק שמביא בידו, המשנה היא כבן חכינאי.",
    "en": "As written, one who bathes in cave water or Tiberias water may not carry his towels home, but ten people may carry one towel. Cave water is hot like Tiberias water. From \"one who bathes\" it follows that bathing is only after the fact, and by implication rinsing is allowed from the outset, which is the view of Rabbi Shimon. Both clauses teach a novelty: one person, even with ten towels, will come to wring them, while many remind each other. And for Rabbi Yochanan, who rules that he may carry it home, the Mishnah is the view of Ben Chachinai."
   },
