   "text": "סָכִין וּמְמַשְׁמְשִׁין בִּבְנֵי מֵעַיִם, אֲבָל לֹא מִתְעַמְּלִין וְלֹא מִתְגָּרְדִין. אֵין יוֹרְדִין לְקוֹרְדִּימָה, וְאֵין עוֹשִׂין אַפִּקְטְוִזִין, וְאֵין מְעַצְּבִין אֶת הַקָּטָן, וְאֵין מַחֲזִירִין אֶת הַשֶּׁבֶר. מִי שֶׁנִּפְרְקָה יָדוֹ וְרַגְלוֹ, לֹא יִטְרְפֵם בְּצוֹנֵן, אֲבָל רוֹחֵץ הוּא כְדַרְכּוֹ, וְאִם נִתְרַפָּא נִתְרַפָּא:",
   "gap": {
    "he": "לפי לשון המשנה, סכים וממשמשים אבל לא מתעמלים, אין יורדים לקורדימא, אין עושים אפיקטויזין, אין מעצבים את הקטן ואין מחזירים את השבר. סיכה ומשמוש צריכים שינוי מן החול: לרבי חמא בר חנינא סך ואחר כך ממשמש, ולרבי יוחנן סך וממשמש בבת אחת. בכלל 'מתעמלין' אסור לעמוד בקרקעית דיומסת. קורדימא אסורה משום הטיט. אפיקטויזין אסור רק בסם ולא ביד. מעצבין האסור הוא בחומרי שדרה שנראה כבונה, אבל ללפף תינוק מותר. ושמואל פוסק שמחזירים את השבר.",
    "en": "As written, one may oil and massage but not exercise, not go down into kordima mud, not induce vomiting, not shape a baby's limbs, and not set a fracture. Oiling and massaging need a change from the weekday: for Rabbi Chama bar Chanina he oils and then massages, for Rabbi Yochanan he does both at once. \"Exercise\" includes standing at the bottom of the Diomses spring. Kordima is forbidden because of the mud. Inducing vomiting is forbidden only with a drug, not by hand. The forbidden shaping is straightening the spine, which looks like building, but swaddling a baby is permitted. And Shmuel rules that a fracture may be set."
   },
