   "name": {
    "he": "מונה אדם את אורחיו",
    "en": "Counting guests and portions"
   },
   "text": "מוֹנֶה אָדָם אֶת אוֹרְחָיו וְאֶת פַּרְפְּרוֹתָיו מִפִּיו, אֲבָל לֹא מִן הַכְּתָב. וּמֵפִיס עִם בָּנָיו וְעִם בְּנֵי בֵיתוֹ עַל הַשֻּׁלְחָן, וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לַעֲשׂוֹת מָנָה גְדוֹלָה כְּנֶגֶד קְטַנָּה, מִשּׁוּם קֻבְיָא. וּמַטִּילִין חֲלָשִׁים עַל הַקָּדָשִׁים בְּיוֹם טוֹב, אֲבָל לֹא עַל הַמָּנוֹת:",
   "gap": {
    "he": "לפי לשון המשנה, מונה אדם את אורחיו מפיו אבל לא מן הכתב, מפיס עם בניו ובני ביתו ובלבד שלא יתכוון למנה גדולה כנגד קטנה, ומטילים חלשים על הקדשים אבל לא על המנות. איסור הכתב הוא לרב ביבי גזירה שמא ימחוק, ולאביי שמא יקרא בשטרי הדיוטות, ונפקא מינה בכתוב על כותל גבוה. 'עם בניו' בא למעט אחרים, שבני חבורה המקפידים עוברים משום מדה ומנין, ובניו מותר אפילו ברבית כדי להטעימם טעם רבית. חסורי מחסרא: עם בניו מותר אפילו מנה גדולה כנגד קטנה, ולאחרים אסור אף בחול משום קוביא. 'אבל לא על המנות' פירושו מנות של חול ביום טוב, ו'חלשים' הוא לשון גורל.",
    "en": "As written, one may count his guests by mouth but not from writing, cast lots with his children and household provided he does not aim for a large portion against a small one, and cast lots over sacrificial portions on Yom Tov but not over other portions. The writing ban is, for Rav Bibi, a decree lest he erase, and for Abaye lest he read ordinary documents, with a practical difference where it is written high on a wall. \"With his children\" excludes others, since members of a group who are particular violate measuring and counting, while with his children it is allowed even with interest, to give them a taste of interest. Something is missing: with his children even a large portion against a small one is allowed, and with others it is forbidden even on a weekday as gambling. \"But not over portions\" means weekday portions on Yom Tov, and \"chalashim\" means lots."
   },
