   "text": "מַחְשִׁיכִין עַל הַתְּחוּם לְפַקֵּחַ עַל עִסְקֵי כַלָּה, וְעַל עִסְקֵי הַמֵּת לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין. גּוֹי שֶׁהֵבִיא חֲלִילִין בְּשַׁבָּת, לֹא יִסְפֹּד בָּהֶן יִשְׂרָאֵל, אֶלָּא אִם כֵּן בָּאוּ מִמָּקוֹם קָרוֹב. עָשׂוּ לוֹ אָרוֹן וְחָפְרוּ לוֹ קֶבֶר, יִקָּבֵר בּוֹ יִשְׂרָאֵל, וְאִם בִּשְׁבִיל יִשְׂרָאֵל, לֹא יִקָּבֵר בּוֹ עוֹלָמִית:",
   "gap": {
    "he": "לפי לשון המשנה, גוי שהביא חלילים בשבת לא יספוד בהם ישראל אלא אם כן באו ממקום קרוב, וארון וקבר שעשה גוי יקבר בו ישראל. נחלקו מהו מקום קרוב: לרב מקום קרוב ממש, ולשמואל חוששים שמא לנו מחוץ לחומה. המשנה מדויקת כשמואל, שבארון וקבר מותר מספק. ומדוע אין צריך להמתין בכדי שיעשו: לעולא בקבר העומד בדרך המלך, ולרבי אבהו בארון של מת המוטל על קברו.",
    "en": "As written, if a gentile brought flutes on Shabbos a Jew may not use them for a eulogy unless they came from nearby, and a coffin or grave a gentile made may be used for a Jew. They disagree what \"nearby\" means: for Rav literally nearby, for Shmuel we suspect they stayed overnight just outside the wall. The Mishnah fits Shmuel, since the coffin and grave are allowed out of doubt. And why one need not wait the time it takes to make them: for Ulla the grave stands on the main road, and for Rabbi Abahu the coffin belongs to a body lying by its grave."
   },
