   "name": {
    "he": "עושין כל צרכי המת",
    "en": "Tending to the dead"
   },
   "text": "עוֹשִׂין כָּל צָרְכֵי הַמֵּת, סָכִין וּמְדִיחִין אוֹתוֹ, וּבִלְבַד שֶׁלֹּא יָזִיזוּ בוֹ אֵבֶר. שׁוֹמְטִין אֶת הַכַּר מִתַּחְתָּיו וּמַטִּילִין אוֹתוֹ עַל הַחֹל בִּשְׁבִיל שֶׁיַּמְתִּין. קוֹשְׁרִים אֶת הַלֶּחִי, לֹא שֶׁיַּעֲלֶה, אֶלָּא שֶׁלֹּא יוֹסִיף. וְכֵן קוֹרָה שֶׁנִּשְׁבְּרָה, סוֹמְכִין אוֹתָהּ בְּסַפְסָל אוֹ בַּאֲרֻכּוֹת הַמִּטָּה, לֹא שֶׁתַּעֲלֶה, אֶלָּא שֶׁלֹּא תוֹסִיף. אֵין מְעַמְּצִין אֶת הַמֵּת בְּשַׁבָּת, וְלֹא בְחֹל עִם יְצִיאַת נֶפֶשׁ. וְהַמְעַמֵּץ עִם יְצִיאַת נֶפֶשׁ, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים:",
   "gap": {
    "he": "לפי לשון המשנה, עושים כל צרכי המת, סכים ומדיחים אותו, ואין מעצמים את המת עם יציאת נפש. סיכה והדחה מותרות במת אף שבקרקע אסור, משום שמת בקרקע לא מיחלף. 'כל' בא לרבות כלי מיקר וכלי מתכות שמניחים על כריסו שלא תפוח. והמעצים עם יציאת נפש שופך דמים, כנר שכבה והולך ואדם מניח אצבעו עליו.",
    "en": "As written, one may do all the needs of the dead, oiling and rinsing him, and one may not close the eyes at the moment of death. Oiling and rinsing a body are allowed even though doing so to a floor is forbidden, since a body is not confused with a floor. \"All\" includes cooling vessels and metal vessels placed on his belly so it will not swell. And one who closes the eyes at the moment of death spills blood, like a flickering lamp that goes out when a finger is placed on it."
   },
