   "text": "מַתִּירִין פְּקִיעֵי עָמִיר לִפְנֵי בְהֵמָה, וּמְפַסְפְּסִים אֶת הַכֵּפִין, אֲבָל לֹא אֶת הַזֵּרִין. אֵין מְרַסְּקִין לֹא אֶת הַשַּׁחַת וְלֹא אֶת הֶחָרוּבִין לִפְנֵי בְהֵמָה, בֵּין דַּקָּה בֵּין גַּסָּה. רַבִּי יְהוּדָה מַתִּיר בֶּחָרוּבִין לַדַּקָּה:",
   "gap": {
    "he": "לפי לשון המשנה, מתירים פקיעי עמיר לפני בהמה ומפספסים את הכיפין אבל לא את הזירין, ואין מרסקים שחת וחרובין. רב הונא ורב יהודה חולקים בפירוש המילים: לרב הונא פקיעין וכיפין אחד, והזירין אסורים בכל, כי טורחים באוכל אבל לא עושים אוכל. לרב יהודה פקיעין וזירין אחד, ופספוס אסור בהם, כי עושים אוכל אבל לא טורחים באוכל. ולרב הונא השחת שאין מרסקים היא קשה כחרובין, כגון בעילי זוטרי.",
    "en": "As written, one may untie bundles of fodder before an animal and loosen kifin but not zirin, and may not crush fodder grass or carobs. Rav Huna and Rav Yehuda disagree on the words: for Rav Huna bundles and kifin are the same and zirin are forbidden entirely, because one may take trouble with food but not make something into food. For Rav Yehuda bundles and zirin are the same and loosening them is forbidden, because one may make something into food but not take trouble with food. And for Rav Huna the grass one may not crush is hard like carobs, such as small stalks."
   },
